import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'pg-advanced-l4-001', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'What is logical decoding in PostgreSQL?', options: ['Logical decoding translates the Write-Ahead Log (WAL) into a logical change stream — it converts physical WAL records into a structured format (INSERT/UPDATE/DELETE operations with row data) using output plugins, enabling change data capture (CDC) and logical replication', 'Logical decoding converts SQL queries into execution plans', 'Logical decoding compresses WAL files for storage', 'Logical decoding decrypts encrypted database files'], correctAnswer: 0, explanation: 'Logical decoding reads the WAL (Write-Ahead Log) and produces a stream of logical changes (row-level inserts, updates, deletes) using output plugins. This is the foundation for logical replication, change data capture (CDC) tools like Debezium, and custom replication solutions. Unlike physical replication (streaming the raw WAL), logical decoding produces a structured, filterable change stream that can target specific tables and databases.', codeSnippet: "-- Enable logical decoding:\n-- postgresql.conf: wal_level = logical\n\n-- Create a replication slot:\nSELECT pg_create_logical_replication_slot(\n  'my_slot', 'pgoutput'\n);\n\n-- Peek at changes (without consuming):\nSELECT * FROM pg_logical_slot_peek_changes(\n  'my_slot', NULL, NULL\n);\n\n-- Consume changes:\nSELECT * FROM pg_logical_slot_get_changes(\n  'my_slot', NULL, NULL\n);\n\n-- List replication slots:\nSELECT slot_name, plugin, active, restart_lsn\nFROM pg_replication_slots;\n\n-- Drop slot when done:\nSELECT pg_drop_replication_slot('my_slot');", tags: ['advanced', 'logical-decoding', 'wal', 'cdc'] },
  { id: 'pg-advanced-l4-002', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'What are output plugins in logical decoding?', options: ['Plugins that format query output for display', 'Plugins that compress WAL segments', 'Output plugins determine the format of the decoded change stream — pgoutput (built-in, used by logical replication) produces a binary protocol, test_decoding outputs human-readable text, and third-party plugins like wal2json produce JSON for CDC tools', 'Plugins that route output to different storage systems'], correctAnswer: 1, explanation: 'Output plugins are loaded by the replication slot and transform WAL entries into a specific format. pgoutput is the built-in plugin used by PostgreSQL logical replication. test_decoding produces human-readable output for testing. wal2json generates JSON objects for each change, which is popular with CDC tools like Debezium. Custom plugins can be written in C to produce any desired format. The plugin is specified when creating the replication slot.', codeSnippet: "-- Create slot with test_decoding (human-readable):\nSELECT pg_create_logical_replication_slot(\n  'test_slot', 'test_decoding'\n);\n\n-- Make some changes:\nINSERT INTO users (name) VALUES ('Alice');\nUPDATE users SET name = 'Bob' WHERE id = 1;\nDELETE FROM users WHERE id = 1;\n\n-- Read decoded changes:\nSELECT * FROM pg_logical_slot_get_changes(\n  'test_slot', NULL, NULL\n);\n-- lsn     | xid | data\n-- 0/1234  | 100 | BEGIN 100\n-- 0/1235  | 100 | table public.users: INSERT: id[int]=1 name[text]='Alice'\n-- 0/1236  | 100 | table public.users: UPDATE: id[int]=1 name[text]='Bob'\n-- 0/1237  | 100 | table public.users: DELETE: id[int]=1\n-- 0/1238  | 100 | COMMIT 100\n\n-- wal2json plugin (JSON output):\nSELECT pg_create_logical_replication_slot(\n  'json_slot', 'wal2json'\n);", tags: ['advanced', 'logical-decoding', 'output-plugins', 'wal2json'] },
  { id: 'pg-advanced-l4-003', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'How do replication slots work with logical decoding?', options: ['Replication slots are physical disk partitions', 'Replication slots store decoded changes in a queue table', 'Replication slots track the consumer position in the WAL stream — they ensure WAL segments are retained until the consumer has processed them, preventing data loss, but unconsumed slots can cause WAL accumulation and disk space issues', 'Replication slots are connection pools for replication'], correctAnswer: 2, explanation: 'A replication slot maintains a pointer to the last WAL position consumed by the subscriber. PostgreSQL retains all WAL segments after this position, ensuring no changes are lost even if the consumer disconnects. However, if a consumer stops processing, WAL files accumulate indefinitely, potentially filling the disk. Use max_slot_wal_keep_size (PG 13+) to limit retention. Monitor with pg_replication_slots and pg_stat_replication.', codeSnippet: "-- Check replication slot status:\nSELECT\n  slot_name,\n  plugin,\n  active,\n  restart_lsn,\n  confirmed_flush_lsn,\n  pg_size_pretty(\n    pg_wal_lsn_diff(\n      pg_current_wal_lsn(),\n      restart_lsn\n    )\n  ) AS retained_wal\nFROM pg_replication_slots;\n\n-- Limit WAL retention (PG 13+):\n-- postgresql.conf:\n-- max_slot_wal_keep_size = '10GB'\n\n-- Monitor WAL usage:\nSELECT\n  pg_size_pretty(pg_wal_lsn_diff(\n    pg_current_wal_lsn(), restart_lsn\n  )) AS lag\nFROM pg_replication_slots\nWHERE slot_name = 'my_slot';\n\n-- Emergency: drop stuck slot\nSELECT pg_drop_replication_slot('stuck_slot');", tags: ['advanced', 'logical-decoding', 'replication-slots', 'wal-retention'] },
  { id: 'pg-advanced-l4-004', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Background Workers', question: 'What are custom background workers in PostgreSQL?', options: ['Background workers are cron jobs managed by pg_cron', 'Background workers are connection pool threads', 'Custom background workers are C-language processes registered with PostgreSQL that run alongside the server — they can perform background tasks like custom replication, periodic maintenance, monitoring, or data processing without client connections', 'Background workers are operating system services'], correctAnswer: 3, explanation: 'Background workers are server processes managed by the PostgreSQL postmaster. They start automatically with the server and can access shared memory and the SPI (Server Programming Interface) for running SQL. Workers are registered in shared_preload_libraries via the RegisterBackgroundWorker API. They are used by extensions like pg_cron, pglogical, and TimescaleDB for autonomous background processing. Custom workers require C programming.', codeSnippet: "-- Background workers are configured via C extensions\n-- and shared_preload_libraries in postgresql.conf:\n-- shared_preload_libraries = 'my_worker'\n\n-- Monitor background workers:\nSELECT pid, datname, application_name, backend_type\nFROM pg_stat_activity\nWHERE backend_type = 'background worker';\n\n-- Common background worker extensions:\n-- pg_cron: scheduled SQL job execution\n-- pg_partman: automatic partition management\n-- pglogical: logical replication\n\n-- Check max workers:\nSHOW max_worker_processes;  -- default: 8\nSHOW max_parallel_workers;  -- subset for parallel queries\n\n-- View registered workers (PG 14+):\n-- pg_stat_activity shows all backends including workers", tags: ['advanced', 'background-workers', 'server-processes', 'extensions'] },
  { id: 'pg-advanced-l4-005', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'JIT Compilation', question: 'What is JIT compilation in PostgreSQL and how do you tune it?', options: ['JIT is Java In Time compilation for JDBC drivers', 'JIT compiles SQL into stored procedures', 'JIT (Just-In-Time) compilation uses LLVM to compile query expressions, tuple deforming, and WHERE clauses into native machine code at runtime — controlled by jit_above_cost, jit_inline_above_cost, and jit_optimize_above_cost thresholds', 'JIT pre-compiles all queries at server startup'], correctAnswer: 0, explanation: 'PostgreSQL JIT (added in PG 11) uses LLVM to compile expression evaluation and tuple deforming into native code during query execution. It benefits complex analytical queries with many expressions but adds compilation overhead that hurts simple queries. jit_above_cost (default 100000) enables JIT for queries with estimated cost above this threshold. jit_inline_above_cost (default 500000) enables function inlining. jit_optimize_above_cost (default 500000) enables LLVM optimization passes.', codeSnippet: "-- Check if JIT is available:\nSELECT name, setting FROM pg_settings\nWHERE name LIKE 'jit%';\n\n-- Enable/disable JIT:\nSET jit = on;  -- default: on (if available)\n\n-- Tune thresholds:\nSET jit_above_cost = 100000;         -- enable JIT\nSET jit_inline_above_cost = 500000;  -- inline functions\nSET jit_optimize_above_cost = 500000; -- LLVM optimizations\n\n-- Lower thresholds for more aggressive JIT:\nSET jit_above_cost = 10000;  -- JIT more queries\n\n-- Disable JIT for OLTP workloads:\nSET jit = off;  -- or very high threshold\n\n-- Check JIT in EXPLAIN:\nEXPLAIN (ANALYZE, VERBOSE)\nSELECT complex_expression FROM large_table;\n-- JIT:\n--   Functions: 15\n--   Options: Inlining true, Optimization true\n--   Timing: Generation 1.2 ms, Inlining 5.3 ms,\n--           Optimization 12.1 ms, Emission 8.4 ms", tags: ['advanced', 'jit-compilation', 'llvm', 'performance-tuning'] },
  { id: 'pg-advanced-l4-006', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'JIT Compilation', question: 'When should you disable JIT compilation in PostgreSQL?', options: ['JIT should never be disabled', 'Disable JIT only on Windows systems', 'Disable JIT for OLTP workloads with many short, simple queries — the compilation overhead (typically 10-50ms) can be significant for queries that themselves execute in milliseconds, and JIT provides no benefit for simple index lookups or point queries', 'Disable JIT when using prepared statements'], correctAnswer: 1, explanation: 'JIT helps analytical queries (complex expressions, large scans) but hurts OLTP queries (simple lookups, point queries). The compilation time (generation + inlining + optimization + emission) can exceed the query execution time for short queries. Symptoms of JIT overhead: increased p99 latency, EXPLAIN showing JIT time exceeding actual execution time. Solutions: set jit = off per session/transaction for OLTP, or raise jit_above_cost to a very high value.', codeSnippet: "-- Diagnose JIT overhead:\nEXPLAIN (ANALYZE, BUFFERS)\nSELECT * FROM users WHERE id = 42;\n-- Execution Time: 0.5 ms\n-- JIT:\n--   Generation: 2.1 ms   -- JIT took 4x longer!\n--   Optimization: 5.3 ms\n\n-- Disable for OLTP sessions:\nSET jit = off;\n\n-- Or per-function:\nCREATE FUNCTION fast_lookup(uid INT)\nRETURNS users AS $$\nBEGIN\n  SET LOCAL jit = off;\n  RETURN QUERY SELECT * FROM users WHERE id = uid;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Keep JIT for analytics:\n-- High jit_above_cost skips simple queries:\nSET jit_above_cost = 1000000;\n-- Only JIT queries costing 1M+ plan units\n\n-- Per-role settings:\nALTER ROLE oltp_user SET jit = off;\nALTER ROLE analyst SET jit = on;", tags: ['advanced', 'jit-compilation', 'oltp', 'disable-jit'] },
  { id: 'pg-advanced-l4-007', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Spatial Indexing', question: 'How do you optimize PostGIS spatial indexing for large datasets?', options: ['Use B-tree indexes on geometry columns', 'Spatial indexes cannot be optimized beyond default GiST', 'Use GiST indexes with fillfactor tuning, consider BRIN indexes for naturally ordered spatial data, create partial indexes for frequently queried regions, and use SP-GiST for point-only data — combined with CLUSTER on the spatial index for physical row ordering', 'Only use hash indexes for spatial data'], correctAnswer: 2, explanation: 'Advanced spatial indexing strategies: 1) GiST with lower fillfactor (e.g., 90%) for write-heavy tables. 2) BRIN indexes for data with natural spatial ordering (much smaller than GiST). 3) SP-GiST for point data using quadtree partitioning. 4) Partial GiST indexes for hot regions. 5) CLUSTER on the spatial index to physically order rows by location, improving cache locality. 6) Functional indexes on ST_Transform for frequently-used CRS transformations.', codeSnippet: "-- Standard GiST (good general purpose):\nCREATE INDEX idx_geom_gist\n  ON spatial_data USING gist (geom)\n  WITH (fillfactor = 90);\n\n-- BRIN for naturally ordered data (tiny index):\nCREATE INDEX idx_geom_brin\n  ON gps_tracks USING brin (location)\n  WITH (pages_per_range = 32);\n-- Requires data inserted in spatial order!\n\n-- SP-GiST for points (quadtree):\nCREATE INDEX idx_points_spgist\n  ON sensors USING spgist (location);\n\n-- Partial index for hot region:\nCREATE INDEX idx_nyc_area\n  ON incidents USING gist (location)\n  WHERE ST_Within(location,\n    ST_MakeEnvelope(-74.3, 40.4, -73.7, 40.9, 4326));\n\n-- CLUSTER for physical ordering:\nCLUSTER spatial_data USING idx_geom_gist;\n-- Rows physically ordered by spatial proximity", tags: ['advanced', 'spatial-indexing', 'gist-optimization', 'brin-spatial'] },
  { id: 'pg-advanced-l4-008', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Custom Operators', question: 'How do you create custom operators in PostgreSQL?', options: ['Custom operators require modifying PostgreSQL source code', 'Use CREATE FUNCTION only — operators are just syntax', 'Use CREATE OPERATOR to define a new operator symbol that calls a function — specifying the left and right operand types, the implementing function, commutator, negator, and optional restriction/join selectivity estimators', 'Operators can only be single characters'], correctAnswer: 3, explanation: 'CREATE OPERATOR defines a new operator that calls a specified function. Operators can be unary (prefix/postfix) or binary. The operator name can use symbols like @>, &&, ~~, etc. Commutator and negator help the optimizer rewrite expressions. Restriction and join selectivity estimators (RESTRICT, JOIN) help the planner estimate cardinality. Custom operators are essential for creating operator classes for custom index types.', codeSnippet: "-- Create a similarity operator:\nCREATE FUNCTION text_similar(a TEXT, b TEXT)\nRETURNS BOOLEAN AS $$\nBEGIN\n  RETURN similarity(a, b) > 0.5;\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE;\n\nCREATE OPERATOR ~~~ (\n  FUNCTION = text_similar,\n  LEFTARG = TEXT,\n  RIGHTARG = TEXT,\n  COMMUTATOR = ~~~,  -- a ~~~ b = b ~~~ a\n  RESTRICT = eqsel,   -- use equality selectivity\n  JOIN = eqjoinsel\n);\n\n-- Use the custom operator:\nSELECT * FROM products\nWHERE name ~~~ 'laptop';\n\n-- Create a distance operator:\nCREATE OPERATOR <#> (\n  FUNCTION = my_distance,\n  LEFTARG = point,\n  RIGHTARG = point,\n  COMMUTATOR = <#>\n);", tags: ['advanced', 'custom-operators', 'create-operator', 'extensibility'] },
  { id: 'pg-advanced-l4-009', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Row-Level Security', question: 'How do you implement row-level security (RLS) in PostgreSQL?', options: ['Use views with WHERE clauses for each user', 'Use GRANT/REVOKE on individual rows', 'Use ALTER TABLE ... ENABLE ROW LEVEL SECURITY and CREATE POLICY — RLS policies define which rows each user can see and modify, enforced transparently at the database level regardless of how the table is accessed', 'RLS requires a third-party extension'], correctAnswer: 0, explanation: 'Row-Level Security (RLS) adds automatic WHERE conditions to all queries against a table based on the current user or session context. Policies can be defined for SELECT, INSERT, UPDATE, and DELETE independently. The table owner bypasses RLS by default (use FORCE ROW LEVEL SECURITY to include owners). RLS is implemented in the query rewriter, so it applies to all access paths including functions, views, and direct table access.', codeSnippet: "-- Enable RLS on a table:\nALTER TABLE documents\n  ENABLE ROW LEVEL SECURITY;\n\n-- Create policy: users see only their own rows:\nCREATE POLICY user_isolation ON documents\n  USING (owner_id = current_setting('app.user_id')::INT);\n\n-- Separate policies for read vs write:\nCREATE POLICY select_policy ON documents\n  FOR SELECT\n  USING (owner_id = current_setting('app.user_id')::INT\n    OR is_public = TRUE);\n\nCREATE POLICY insert_policy ON documents\n  FOR INSERT\n  WITH CHECK (owner_id = current_setting('app.user_id')::INT);\n\n-- Set user context:\nSET app.user_id = '42';\nSELECT * FROM documents;\n-- Only sees rows where owner_id = 42 or is_public\n\n-- Force RLS for table owner too:\nALTER TABLE documents FORCE ROW LEVEL SECURITY;", tags: ['advanced', 'row-level-security', 'rls', 'create-policy'] },
  { id: 'pg-advanced-l4-010', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Row-Level Security', question: 'How do you implement multi-tenant data isolation with RLS?', options: ['Use separate databases for each tenant', 'Use schema-per-tenant approach only', 'Create RLS policies that filter by tenant_id — combined with a session variable (SET app.tenant_id) set at connection time, all queries automatically filter to the current tenant without application code changes', 'Multi-tenancy requires application-level filtering only'], correctAnswer: 1, explanation: 'RLS-based multi-tenancy stores all tenants in the same tables and uses policies to enforce isolation. The tenant_id is set as a session variable when the application connects. All queries automatically include the tenant filter. This is simpler than schema-per-tenant (no schema management) and more secure than application filtering (cannot be bypassed). Performance is good because the policy becomes part of the query plan and can use indexes.', codeSnippet: "-- Multi-tenant table:\nCREATE TABLE orders (\n  id SERIAL PRIMARY KEY,\n  tenant_id INT NOT NULL,\n  customer_name TEXT,\n  total NUMERIC\n);\n\nCREATE INDEX ON orders (tenant_id);\nALTER TABLE orders ENABLE ROW LEVEL SECURITY;\n\n-- RLS policy:\nCREATE POLICY tenant_isolation ON orders\n  USING (tenant_id = current_setting('app.tenant_id')::INT)\n  WITH CHECK (tenant_id = current_setting('app.tenant_id')::INT);\n\n-- Application sets tenant on connect:\nSET app.tenant_id = '100';\n\n-- All queries auto-filtered:\nSELECT * FROM orders;\n-- Only sees tenant 100's orders\n\nINSERT INTO orders (tenant_id, customer_name, total)\nVALUES (200, 'Alice', 50.00);\n-- ERROR: new row violates RLS policy\n-- (tenant_id 200 != current tenant 100)\n\n-- Admin bypass:\nCREATE POLICY admin_bypass ON orders\n  TO admin_role\n  USING (TRUE);", tags: ['advanced', 'row-level-security', 'multi-tenancy', 'data-isolation'] },
  { id: 'pg-advanced-l4-011', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Generated Columns', question: 'What are generated columns in PostgreSQL?', options: ['Columns that auto-increment using sequences', 'Columns with DEFAULT values', 'Generated columns are computed automatically from other columns — defined with GENERATED ALWAYS AS (expression) STORED, they are calculated on write and stored physically, staying automatically synchronized when the source columns change', 'Columns that generate random values'], correctAnswer: 2, explanation: 'Generated columns (added in PG 12) are virtual columns whose values are automatically computed from an expression referencing other columns in the same row. STORED generated columns are physically stored and updated automatically on INSERT/UPDATE. They cannot be written to directly. Use cases include: full_name from first_name + last_name, tsvector for full-text search, computed hashes, normalized values, and derived metrics.', codeSnippet: "-- Generated column examples:\nCREATE TABLE products (\n  id SERIAL PRIMARY KEY,\n  name TEXT NOT NULL,\n  price NUMERIC NOT NULL,\n  tax_rate NUMERIC DEFAULT 0.2,\n  price_with_tax NUMERIC\n    GENERATED ALWAYS AS (price * (1 + tax_rate)) STORED,\n  name_search TSVECTOR\n    GENERATED ALWAYS AS (to_tsvector('english', name)) STORED,\n  name_lower TEXT\n    GENERATED ALWAYS AS (lower(name)) STORED\n);\n\nINSERT INTO products (name, price)\nVALUES ('Laptop Pro', 999.99);\n\nSELECT name, price, price_with_tax FROM products;\n-- Laptop Pro | 999.99 | 1199.988\n\n-- Cannot write to generated columns:\nUPDATE products SET price_with_tax = 1000;\n-- ERROR: cannot insert/update generated column\n\n-- Index on generated column:\nCREATE INDEX ON products USING gin (name_search);", tags: ['advanced', 'generated-columns', 'computed-columns', 'stored'] },
  { id: 'pg-advanced-l4-012', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Generated Columns', question: 'What are the limitations of generated columns in PostgreSQL?', options: ['Generated columns have no limitations', 'They can only reference numeric columns', 'Generated columns cannot reference other generated columns, cannot use subqueries or aggregate functions in the expression, only support STORED (not VIRTUAL), and the expression must be IMMUTABLE — volatile functions like now() or random() are not allowed', 'They are limited to text type output'], correctAnswer: 3, explanation: 'Key limitations: 1) Only STORED mode is supported (PG does not yet support VIRTUAL/computed-on-read). 2) The expression must be IMMUTABLE (no now(), random(), or functions that read other tables). 3) Cannot reference other generated columns. 4) Cannot use subqueries or aggregate functions. 5) Partitioning keys cannot be generated columns. 6) Generated columns add storage overhead since they are physically stored. Future PostgreSQL versions may add VIRTUAL generated columns.', codeSnippet: "-- VALID: IMMUTABLE expression\nCREATE TABLE t (\n  a INT,\n  b INT,\n  c INT GENERATED ALWAYS AS (a + b) STORED  -- OK\n);\n\n-- INVALID: references another generated column\nCREATE TABLE t2 (\n  a INT,\n  b INT GENERATED ALWAYS AS (a * 2) STORED,\n  c INT GENERATED ALWAYS AS (b + 1) STORED  -- ERROR!\n);\n\n-- INVALID: volatile function\nCREATE TABLE t3 (\n  name TEXT,\n  created TEXT GENERATED ALWAYS AS (now()::TEXT) STORED\n  -- ERROR: generation expression is not immutable\n);\n\n-- INVALID: subquery\nCREATE TABLE t4 (\n  dept_id INT,\n  dept_name TEXT GENERATED ALWAYS AS (\n    (SELECT name FROM depts WHERE id = dept_id)\n  ) STORED  -- ERROR: cannot use subquery\n);", tags: ['advanced', 'generated-columns', 'limitations', 'immutable'] },
  { id: 'pg-advanced-l4-013', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Parallel Query', question: 'How do you tune parallel query execution in PostgreSQL?', options: ['Parallel queries are always optimal by default', 'Use PARALLEL keyword in SELECT statements', 'Configure max_parallel_workers_per_gather, parallel_tuple_cost, parallel_setup_cost, and min_parallel_table_scan_size — these parameters control how many workers are used, when parallelism is beneficial, and the minimum table size for parallel scans', 'Parallel queries require a special PostgreSQL build'], correctAnswer: 0, explanation: 'PostgreSQL parallel query uses background workers to execute parts of a query simultaneously. Key parameters: max_parallel_workers_per_gather (max workers per Gather node, default 2), parallel_tuple_cost (cost of passing a tuple from worker to leader, default 0.1), parallel_setup_cost (cost of starting a worker, default 1000), min_parallel_table_scan_size (minimum table size for parallel seq scan, default 8MB), min_parallel_index_scan_size (for index scans, default 512KB).', codeSnippet: "-- Check parallel settings:\nSHOW max_worker_processes;          -- 8\nSHOW max_parallel_workers;          -- 8\nSHOW max_parallel_workers_per_gather; -- 2\n\n-- Increase parallelism:\nSET max_parallel_workers_per_gather = 4;\n\n-- Lower thresholds for more parallelism:\nSET min_parallel_table_scan_size = '1MB';\nSET parallel_setup_cost = 100;\nSET parallel_tuple_cost = 0.01;\n\n-- Force parallelism for testing:\nSET force_parallel_mode = on;\n\n-- Check parallel execution:\nEXPLAIN (ANALYZE)\nSELECT COUNT(*) FROM large_table\nWHERE complex_condition;\n-- Gather (actual rows=1 loops=1)\n--   Workers Planned: 4\n--   Workers Launched: 4\n--   -> Parallel Seq Scan on large_table\n\n-- Per-table parallelism:\nALTER TABLE large_table\n  SET (parallel_workers = 8);", tags: ['advanced', 'parallel-query', 'tuning', 'workers'] },
  { id: 'pg-advanced-l4-014', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Parallel Query', question: 'What operations cannot be parallelized in PostgreSQL?', options: ['All operations can be parallelized', 'Only SELECT can be parallelized', 'Queries writing data (INSERT/UPDATE/DELETE), queries in serializable isolation, queries using cursors, queries calling PARALLEL UNSAFE functions, and queries in functions marked PARALLEL RESTRICTED cannot use parallel workers in their parallel-restricted portions', 'Only aggregate functions are parallelized'], correctAnswer: 1, explanation: 'Parallel query restrictions: 1) DML statements (INSERT/UPDATE/DELETE) cannot parallelize the write portion (but parallel scans in subqueries are possible since PG 14). 2) Serializable isolation prevents parallelism. 3) Cursor queries cannot be parallelized. 4) Functions marked PARALLEL UNSAFE prevent the whole query from going parallel. 5) Temporary table access prevents parallelism. 6) CTE scans (not inlined) may prevent parallelism. 7) The leader always participates as a worker too.', codeSnippet: "-- Check function parallel safety:\nSELECT proname, proparallel\nFROM pg_proc WHERE proname = 'my_func';\n-- 's' = safe, 'r' = restricted, 'u' = unsafe\n\n-- Make functions parallel safe:\nALTER FUNCTION my_pure_func(INT)\n  PARALLEL SAFE;\n\n-- Parallel DML (PG 14+ for underlying scan):\nINSERT INTO target\nSELECT * FROM large_source WHERE condition;\n-- The SELECT scan can be parallel\n\n-- These PREVENT parallelism:\n-- 1. SERIALIZABLE isolation\nSET transaction_isolation = 'serializable';\n-- 2. Cursor queries\nDECLARE cur CURSOR FOR SELECT ...;\n-- 3. PARALLEL UNSAFE functions in WHERE\nSELECT * FROM t WHERE unsafe_func(col);\n\n-- Diagnose why parallel not used:\nSET force_parallel_mode = on;\nEXPLAIN SELECT ...; -- will show if forced", tags: ['advanced', 'parallel-query', 'restrictions', 'parallel-safety'] },
  { id: 'pg-advanced-l4-015', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Custom Operators', question: 'How do you create an operator class for custom index support?', options: ['Operator classes are created automatically for all operators', 'Use CREATE INDEX with custom functions only', 'Use CREATE OPERATOR CLASS to define a set of operators and support functions that enable a custom data type to work with a specific index type (B-tree, GiST, GIN, etc.) — this maps comparison semantics to the index access method', 'Operator classes require C code modifications'], correctAnswer: 2, explanation: 'An operator class tells an index access method how to index a data type. For B-tree, you define operators for <, <=, =, >=, > and a comparison support function. For GiST, you define strategies (overlaps, contains, etc.) and support functions (consistent, union, penalty, etc.). For GIN, you define contains/contained-by operators and extract functions. Operator families group related operator classes for cross-type operations.', codeSnippet: "-- Example: B-tree operator class for a custom type\n-- (assumes my_type and comparison functions exist)\n\nCREATE OPERATOR CLASS my_type_ops\n  DEFAULT FOR TYPE my_type\n  USING btree AS\n  OPERATOR 1 < (my_type, my_type),\n  OPERATOR 2 <= (my_type, my_type),\n  OPERATOR 3 = (my_type, my_type),\n  OPERATOR 4 >= (my_type, my_type),\n  OPERATOR 5 > (my_type, my_type),\n  FUNCTION 1 my_type_cmp(my_type, my_type);\n\n-- Now you can create indexes:\nCREATE INDEX ON my_table USING btree (my_col my_type_ops);\n\n-- GIN operator class (for array-like types):\nCREATE OPERATOR CLASS my_gin_ops\n  FOR TYPE my_array_type\n  USING gin AS\n  OPERATOR 7 @> (my_array_type, my_array_type),\n  OPERATOR 8 <@ (my_array_type, my_array_type),\n  FUNCTION 1 my_compare(internal, my_element_type),\n  FUNCTION 2 my_extract_value(my_array_type, internal);", tags: ['advanced', 'custom-operators', 'operator-class', 'index-support'] },
  { id: 'pg-advanced-l4-016', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Row-Level Security', question: 'How do you combine RLS with views and functions?', options: ['RLS does not apply to views', 'Views automatically bypass RLS', 'RLS is enforced on the underlying tables when accessed through views — however, SECURITY DEFINER functions bypass RLS by default (running as the function owner), so use SECURITY INVOKER or explicit SET ROW SECURITY to maintain RLS enforcement', 'Functions always bypass RLS'], correctAnswer: 3, explanation: 'RLS interacts with views and functions in important ways: Views inherit RLS from base tables when the view creator does not bypass RLS. SECURITY DEFINER functions run as the owner and bypass RLS by default, which can be a security hole. Use SET row_security = on in SECURITY DEFINER functions to force RLS. Or prefer SECURITY INVOKER functions (PG 15+ for views). For views created by superusers or table owners, data may leak without proper configuration.', codeSnippet: "-- View respects RLS (if view owner has RLS):\nCREATE VIEW my_documents AS\nSELECT * FROM documents;\n-- RLS policies on 'documents' still apply\n\n-- SECURITY DEFINER bypasses RLS (dangerous!):\nCREATE FUNCTION get_all_docs()\nRETURNS SETOF documents\nSECURITY DEFINER AS $$\nBEGIN\n  RETURN QUERY SELECT * FROM documents;\nEND;\n$$ LANGUAGE plpgsql;\n-- Returns ALL rows, ignoring RLS!\n\n-- Fix: force RLS in SECURITY DEFINER:\nCREATE FUNCTION get_docs_safe()\nRETURNS SETOF documents\nSECURITY DEFINER\nSET row_security = on  -- force RLS check\nAS $$\nBEGIN\n  RETURN QUERY SELECT * FROM documents;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- PG 15+: SECURITY INVOKER views:\nCREATE VIEW my_docs\n  WITH (security_invoker = true) AS\nSELECT * FROM documents;\n-- RLS uses the querying user, not view owner", tags: ['advanced', 'row-level-security', 'views', 'security-definer'] },
  { id: 'pg-advanced-l4-017', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'How do you use logical decoding for change data capture (CDC)?', options: ['CDC requires proprietary tools only', 'Use WAL archiving for CDC', 'Set up a logical replication slot with wal2json or pgoutput plugin, then consume the change stream from an external application — tools like Debezium connect to the replication slot and stream changes to Kafka, enabling real-time data pipelines', 'CDC is only possible with physical replication'], correctAnswer: 0, explanation: 'CDC with logical decoding: 1) Set wal_level = logical. 2) Create a replication slot with an appropriate plugin (wal2json for JSON, pgoutput for binary). 3) An external consumer (Debezium, pg_recvlogical, custom app) connects to the slot using the streaming replication protocol. 4) Changes are streamed in commit order. 5) The consumer acknowledges progress, advancing the slot position. This enables real-time data integration without triggers or polling.', codeSnippet: "-- PostgreSQL side:\n-- postgresql.conf: wal_level = logical\n-- pg_hba.conf: allow replication connections\n\n-- Create publication (for pgoutput):\nCREATE PUBLICATION my_pub\n  FOR TABLE orders, products, customers;\n\n-- Or for all tables:\nCREATE PUBLICATION all_changes\n  FOR ALL TABLES;\n\n-- Using pg_recvlogical CLI:\n-- pg_recvlogical -d mydb --slot=my_slot\n--   --create-slot --plugin=wal2json\n--   --start -f changes.json\n\n-- Monitor CDC lag:\nSELECT slot_name,\n  pg_size_pretty(\n    pg_wal_lsn_diff(pg_current_wal_lsn(), confirmed_flush_lsn)\n  ) AS replication_lag\nFROM pg_replication_slots\nWHERE slot_type = 'logical';\n\n-- Debezium reads from the slot automatically\n-- and publishes to Kafka topics", tags: ['advanced', 'logical-decoding', 'cdc', 'debezium'] },
  { id: 'pg-advanced-l4-018', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Spatial Indexing', question: 'How do you use BRIN indexes for spatial data in PostGIS?', options: ['BRIN indexes do not support spatial data', 'BRIN spatial indexes are identical to GiST', 'BRIN (Block Range INdex) indexes store bounding box summaries for ranges of physical pages — they are extremely small (1000x smaller than GiST) and work well when spatial data is physically clustered, such as GPS tracks ordered by time/location', 'BRIN indexes replace GiST entirely for PostGIS'], correctAnswer: 1, explanation: 'BRIN indexes are minuscule compared to GiST but only effective when the data has physical correlation with the indexed values. For spatial data, this means rows that are geographically close should be stored in nearby physical pages. GPS tracks (inserted chronologically, following a path) and time-series spatial data naturally have this property. BRIN indexes store bounding boxes for ranges of pages (controlled by pages_per_range), making them ideal for massive append-only spatial datasets.', codeSnippet: "-- BRIN spatial index (tiny, for ordered data):\nCREATE INDEX idx_gps_brin\n  ON gps_tracks USING brin (location)\n  WITH (pages_per_range = 64);\n\n-- Compare index sizes:\nSELECT\n  pg_size_pretty(pg_relation_size('idx_gps_gist')) AS gist_size,\n  pg_size_pretty(pg_relation_size('idx_gps_brin')) AS brin_size;\n-- gist_size: 500 MB\n-- brin_size: 500 KB  (1000x smaller!)\n\n-- BRIN works for range queries:\nSELECT * FROM gps_tracks\nWHERE location && ST_MakeEnvelope(...);\n\n-- Check physical correlation:\nSELECT correlation\nFROM pg_stats\nWHERE tablename = 'gps_tracks'\n  AND attname = 'location';\n-- High correlation = BRIN will work well\n\n-- CLUSTER to improve correlation:\nCLUSTER gps_tracks USING idx_location_gist;\n-- Then create BRIN index", tags: ['advanced', 'spatial-indexing', 'brin', 'large-datasets'] },
  { id: 'pg-advanced-l4-019', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Custom Operators', question: 'How do you implement commutator and negator for custom operators?', options: ['Commutator and negator are optional syntax sugar', 'They are automatically inferred by PostgreSQL', 'Commutator tells the optimizer that A op B equals B commutator_op A, and negator tells it that NOT (A op B) equals A negator_op B — these enable the optimizer to flip operand order and simplify NOT expressions for better query plans', 'They only work with numeric operators'], correctAnswer: 2, explanation: 'Commutator and negator are optimizer hints. The commutator of < is >, meaning (a < b) is the same as (b > a). This allows the optimizer to reorder operands to match available indexes. The negator of = is !=, meaning NOT (a = b) is the same as (a != b). Without these hints, the optimizer cannot make these transformations. For B-tree operator classes, these relationships are essential for index scan planning.', codeSnippet: "-- Define paired operators with commutator/negator:\nCREATE FUNCTION ip_contains(cidr, inet)\nRETURNS BOOLEAN AS $$\n  SELECT $1 >> $2;\n$$ LANGUAGE sql IMMUTABLE;\n\nCREATE FUNCTION ip_contained(inet, cidr)\nRETURNS BOOLEAN AS $$\n  SELECT $2 >> $1;\n$$ LANGUAGE sql IMMUTABLE;\n\nCREATE OPERATOR @>> (\n  FUNCTION = ip_contains,\n  LEFTARG = cidr,\n  RIGHTARG = inet,\n  COMMUTATOR = <<@  -- a @>> b means b <<@ a\n);\n\nCREATE OPERATOR <<@ (\n  FUNCTION = ip_contained,\n  LEFTARG = inet,\n  RIGHTARG = cidr,\n  COMMUTATOR = @>>  -- a <<@ b means b @>> a\n);\n\n-- Negator example:\nCREATE OPERATOR !== (\n  FUNCTION = my_not_equal,\n  LEFTARG = my_type,\n  RIGHTARG = my_type,\n  NEGATOR = ===,  -- NOT (a !== b) means a === b\n  COMMUTATOR = !==\n);", tags: ['advanced', 'custom-operators', 'commutator', 'negator'] },
  { id: 'pg-advanced-l4-020', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Row-Level Security', question: 'How do you implement column-level and row-level security together?', options: ['Column and row security cannot be combined', 'Use RLS for columns and views for rows', 'Combine ALTER TABLE ENABLE ROW LEVEL SECURITY with GRANT/REVOKE on specific columns — RLS controls which rows are visible, column privileges control which columns are accessible, providing two-dimensional access control on the same table', 'Use a separate security extension'], correctAnswer: 3, explanation: 'PostgreSQL supports independent column-level and row-level security. Column privileges (GRANT SELECT(col1, col2) ON table TO role) restrict which columns a user can read. RLS policies restrict which rows are visible. Together, they provide fine-grained access control: user A might see columns 1-3 of rows matching condition X, while user B sees columns 2-5 of rows matching condition Y. This is powerful for regulatory compliance.', codeSnippet: "-- Table with sensitive data:\nCREATE TABLE employees (\n  id INT PRIMARY KEY,\n  name TEXT,\n  department TEXT,\n  salary NUMERIC,\n  ssn TEXT,\n  manager_id INT\n);\n\n-- Row-level: managers see their reports only\nALTER TABLE employees ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY manager_sees_reports ON employees\n  FOR SELECT TO manager_role\n  USING (manager_id = current_setting('app.user_id')::INT);\n\n-- Column-level: hide sensitive columns\nREVOKE ALL ON employees FROM hr_role;\nGRANT SELECT (id, name, department) ON employees\n  TO hr_role;\n-- hr_role cannot see salary or ssn\n\n-- Combine both:\n-- manager_role sees: all columns, only their reports\n-- hr_role sees: id/name/dept, all rows (separate policy)\n-- analyst_role sees: aggregated data only (via view)\n\nCREATE POLICY hr_all_rows ON employees\n  FOR SELECT TO hr_role\n  USING (TRUE);  -- all rows, but limited columns", tags: ['advanced', 'row-level-security', 'column-security', 'access-control'] },
  { id: 'pg-advanced-l4-021', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'How do you implement logical replication with filtered publications?', options: ['Logical replication always replicates everything', 'Use views for filtered replication', 'Use CREATE PUBLICATION with WHERE clause (PG 15+) to filter which rows are replicated — combine with column lists to replicate only specific columns, enabling selective data synchronization between databases', 'Filtered replication requires physical replication'], correctAnswer: 0, explanation: 'PostgreSQL 15 added row filtering (WHERE clause) and column lists to publications. This allows replicating only a subset of data: specific tables, specific columns within tables, and specific rows matching a condition. This is useful for replicating only public data to a read replica, synchronizing subset data to edge databases, or filtering out sensitive columns during replication. The filter is applied on the publisher side.', codeSnippet: "-- Filtered publication (PG 15+):\nCREATE PUBLICATION filtered_pub\n  FOR TABLE\n    orders (id, customer_name, total, status)\n      WHERE (status = 'completed'),\n    products (id, name, price)\n      WHERE (active = TRUE);\n\n-- On subscriber:\nCREATE SUBSCRIPTION my_sub\n  CONNECTION 'host=publisher dbname=prod'\n  PUBLICATION filtered_pub;\n\n-- Replicate all tables except sensitive ones:\nCREATE PUBLICATION safe_pub\n  FOR ALL TABLES;\n\n-- Exclude specific tables:\nALTER PUBLICATION safe_pub\n  DROP TABLE secret_data, internal_logs;\n\n-- Column list (PG 15+):\nCREATE PUBLICATION col_pub\n  FOR TABLE users (id, name, email);\n  -- Excludes: ssn, password_hash, etc.\n\n-- Monitor replication:\nSELECT * FROM pg_stat_subscription;", tags: ['advanced', 'logical-decoding', 'filtered-publication', 'logical-replication'] },
  { id: 'pg-advanced-l4-022', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Generated Columns', question: 'How do you use generated columns for full-text search optimization?', options: ['Generated columns cannot store tsvector', 'Use triggers for tsvector maintenance only', 'Create a GENERATED ALWAYS AS column of type tsvector — the tsvector is automatically computed from source text columns and updated whenever they change, with a GIN index on it for efficient full-text search queries', 'Use materialized views for tsvector storage'], correctAnswer: 1, explanation: 'Generated tsvector columns replace the traditional trigger-based approach for maintaining search vectors. The generated column automatically stays in sync with source columns, eliminating the need for custom triggers. Combined with a GIN index, this provides efficient full-text search. The expression must be IMMUTABLE, so you must use the simple text configuration or a wrapper for language-specific configurations.', codeSnippet: "-- Generated tsvector column:\nCREATE TABLE articles (\n  id SERIAL PRIMARY KEY,\n  title TEXT NOT NULL,\n  body TEXT,\n  -- Auto-computed search vector:\n  search_vector TSVECTOR GENERATED ALWAYS AS (\n    setweight(to_tsvector('english', coalesce(title, '')), 'A') ||\n    setweight(to_tsvector('english', coalesce(body, '')), 'B')\n  ) STORED\n);\n\n-- GIN index for fast search:\nCREATE INDEX idx_articles_search\n  ON articles USING gin (search_vector);\n\n-- Search:\nSELECT title,\n  ts_rank(search_vector, q) AS rank\nFROM articles,\n  plainto_tsquery('english', 'database performance') q\nWHERE search_vector @@ q\nORDER BY rank DESC;\n\n-- No trigger needed!\n-- search_vector auto-updates on INSERT/UPDATE", tags: ['advanced', 'generated-columns', 'full-text-search', 'tsvector'] },
  { id: 'pg-advanced-l4-023', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'JIT Compilation', question: 'How does JIT compilation affect query plan caching and prepared statements?', options: ['JIT decisions are cached with the query plan', 'Prepared statements always disable JIT', 'JIT decisions are made at execution time based on the actual query cost — for prepared statements with generic plans, the JIT decision uses the estimated cost which may differ from actual, potentially causing suboptimal JIT choices for varying parameter values', 'JIT only works with ad-hoc queries'], correctAnswer: 2, explanation: 'JIT decisions are made during query execution, not planning. For prepared statements, PostgreSQL may use a generic plan (after 5 executions) where the cost is estimated with average statistics. If the generic plan cost crosses the jit_above_cost threshold, JIT will be used for all executions regardless of actual parameter values. This can cause JIT overhead for simple lookups when the generic plan overestimates cost. Use plan_cache_mode = force_custom_plan to mitigate.', codeSnippet: "-- Prepared statement JIT behavior:\nPREPARE lookup(INT) AS SELECT * FROM large_table WHERE id = $1;\n\n-- First 5 executions: custom plan (no JIT for point query)\nEXECUTE lookup(42); -- fast, no JIT\n\n-- After 5: generic plan may trigger JIT\nEXECUTE lookup(42); -- may now use JIT if generic cost > threshold\n\n-- Force custom plans:\nSET plan_cache_mode = 'force_custom_plan';\n-- Each execution gets its own plan\n\n-- Or disable JIT for this session:\nSET jit = off;\n\n-- Monitor JIT in pg_stat_statements:\nSELECT query,\n  calls,\n  mean_exec_time,\n  jit_functions,\n  jit_generation_time,\n  jit_inlining_time,\n  jit_optimization_time\nFROM pg_stat_statements\nWHERE jit_functions > 0\nORDER BY jit_generation_time DESC;", tags: ['advanced', 'jit-compilation', 'prepared-statements', 'plan-cache'] },
  { id: 'pg-advanced-l4-024', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Custom Operators', question: 'How do you provide selectivity estimators for custom operators?', options: ['Selectivity estimation is handled automatically', 'Use ANALYZE on the operator', 'Specify RESTRICT and JOIN selectivity estimator functions in CREATE OPERATOR — these functions help the query planner estimate how many rows will match the operator condition, enabling accurate cost estimates for query optimization', 'Custom operators always assume 50% selectivity'], correctAnswer: 3, explanation: 'Selectivity estimators are functions that tell the planner what fraction of rows will match an operator condition. RESTRICT is for WHERE clause conditions (e.g., WHERE col op value). JOIN is for join conditions. Without estimators, the planner uses a default (0.5% for restriction, varies for joins) which can produce terrible plans. Built-in estimators include eqsel/eqjoinsel (equality), neqsel/neqjoinsel (not-equal), scalarltsel/scalargtsel (comparison).', codeSnippet: "-- Use built-in selectivity estimators:\nCREATE OPERATOR === (\n  FUNCTION = my_equal,\n  LEFTARG = my_type,\n  RIGHTARG = my_type,\n  RESTRICT = eqsel,     -- equality selectivity\n  JOIN = eqjoinsel      -- equality join selectivity\n);\n\n-- For range/comparison operators:\nCREATE OPERATOR <<< (\n  FUNCTION = my_less_than,\n  LEFTARG = my_type,\n  RIGHTARG = my_type,\n  RESTRICT = scalarltsel,  -- less-than selectivity\n  JOIN = scalarltjoinsel\n);\n\n-- For containment operators:\nCREATE OPERATOR @@@ (\n  FUNCTION = my_contains,\n  LEFTARG = my_type,\n  RIGHTARG = my_type,\n  RESTRICT = contsel,    -- containment selectivity\n  JOIN = contjoinsel\n);\n\n-- Without estimators (bad plans!):\n-- Planner assumes default selectivity\n-- Leading to wrong join orders, scan methods", tags: ['advanced', 'custom-operators', 'selectivity', 'query-planning'] },
  { id: 'pg-advanced-l4-025', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Row-Level Security', question: 'How do you debug and test RLS policies?', options: ['RLS policies cannot be tested', 'Use EXPLAIN to see RLS filters', 'Check policies with pg_policies catalog view, test as different roles using SET ROLE, and use EXPLAIN to verify the policy conditions are appended as filter conditions — also check that the BYPASSRLS attribute is not accidentally granted to test roles', 'Use a special RLS debug mode'], correctAnswer: 0, explanation: 'Debugging RLS: 1) Query pg_policies to see all active policies. 2) Use SET ROLE to switch to different users and verify they see correct rows. 3) EXPLAIN (VERBOSE) shows the policy-appended filter in the query plan. 4) Check for BYPASSRLS privilege (ALTER ROLE ... NOBYPASSRLS). 5) Test edge cases: what happens with no matching policy (default deny), multiple policies (OR logic for permissive, AND for restrictive). 6) Remember table owners bypass RLS unless FORCE ROW LEVEL SECURITY is set.', codeSnippet: "-- View all RLS policies:\nSELECT schemaname, tablename, policyname,\n  permissive, roles, cmd, qual, with_check\nFROM pg_policies\nWHERE tablename = 'documents';\n\n-- Test as different users:\nSET ROLE user_a;\nSELECT * FROM documents; -- see user_a's view\nSET ROLE user_b;\nSELECT * FROM documents; -- see user_b's view\nRESET ROLE;\n\n-- See policy in query plan:\nSET ROLE user_a;\nEXPLAIN (VERBOSE)\nSELECT * FROM documents;\n-- Filter: (owner_id = current_setting(...)::int)\n\n-- Check bypass privileges:\nSELECT rolname, rolbypassrls\nFROM pg_roles\nWHERE rolbypassrls = TRUE;\n\n-- Check if RLS is enabled:\nSELECT relname, relrowsecurity, relforcerowsecurity\nFROM pg_class WHERE relname = 'documents';", tags: ['advanced', 'row-level-security', 'debugging', 'testing'] },
  { id: 'pg-advanced-l4-026', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'How do you handle large transactions and streaming in logical decoding?', options: ['Large transactions are automatically handled', 'Split large transactions before replication', 'Use streaming mode (PG 14+) to stream large in-progress transactions to the subscriber in chunks — instead of buffering the entire transaction in memory, changes are sent as they happen and applied when the transaction commits', 'Large transactions cannot be logically decoded'], correctAnswer: 1, explanation: 'Before PG 14, logical decoding buffered entire transactions in memory (or spilled to disk) before sending. Large transactions (millions of rows) could cause memory issues or delays. PG 14 added streaming mode: in-progress transaction changes are streamed to the subscriber incrementally. The subscriber applies them when the transaction commits (or discards on rollback). This dramatically reduces memory usage and latency for large transactions.', codeSnippet: "-- Enable streaming for large transactions (PG 14+):\nALTER SUBSCRIPTION my_sub\n  SET (streaming = 'on');\n\n-- Control spill-to-disk threshold:\n-- postgresql.conf:\n-- logical_decoding_work_mem = '64MB'\n-- (default: 64MB, per replication slot)\n\n-- Monitor decoding memory:\nSELECT slot_name,\n  pg_size_pretty(total_bytes) AS total_memory,\n  pg_size_pretty(total_bytes - streamed_bytes) AS buffered,\n  spill_txns, spill_count, spill_bytes\nFROM pg_stat_replication_slots;\n\n-- PG 15: parallel apply for subscribers\nALTER SUBSCRIPTION my_sub\n  SET (streaming = 'parallel');\n-- Subscribers apply transactions in parallel\n\n-- Two-phase commit support (PG 15+):\nALTER SUBSCRIPTION my_sub\n  SET (two_phase = 'on');\n-- PREPARE TRANSACTION is replicated", tags: ['advanced', 'logical-decoding', 'streaming', 'large-transactions'] },
  { id: 'pg-advanced-l4-027', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Spatial Indexing', question: 'How do you use SP-GiST indexes for spatial point data?', options: ['SP-GiST and GiST are identical for spatial data', 'SP-GiST does not support spatial data', 'SP-GiST (Space-Partitioned GiST) uses quadtree or k-d tree partitioning for point data — it can be faster than GiST for certain point-only queries because it partitions space into non-overlapping regions, avoiding the bounding box overlap issues of GiST', 'SP-GiST is only for text data'], correctAnswer: 2, explanation: 'SP-GiST uses space-partitioning tree structures (quadtree for 2D points, k-d tree for multi-dimensional data) instead of the balanced tree of GiST. Non-overlapping partitions mean each point belongs to exactly one partition, which can speed up point queries. SP-GiST is effective for point data but does not support complex geometries (lines, polygons) or KNN ordering. For mixed geometry types, GiST remains the better choice.', codeSnippet: "-- SP-GiST index for points:\nCREATE INDEX idx_points_spgist\n  ON sensor_readings\n  USING spgist (location);\n\n-- Compare with GiST:\nCREATE INDEX idx_points_gist\n  ON sensor_readings\n  USING gist (location);\n\n-- SP-GiST works for:\nSELECT * FROM sensor_readings\nWHERE location <@ box '((0,0),(10,10))';  -- containment\n\nSELECT * FROM sensor_readings\nWHERE location << point '(5,5)';  -- strictly left of\n\n-- SP-GiST limitations:\n-- No KNN ordering (<-> operator)\n-- No complex geometry types\n-- No lossy index scans\n\n-- When to use SP-GiST vs GiST:\n-- SP-GiST: point-only data, containment queries\n-- GiST: mixed geometries, KNN, overlap queries\n\n-- SP-GiST for ranges too:\nCREATE INDEX ON bookings\n  USING spgist (daterange(start_date, end_date));", tags: ['advanced', 'spatial-indexing', 'spgist', 'quadtree'] },
  { id: 'pg-advanced-l4-028', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Generated Columns', question: 'How do you use generated columns with JSON data?', options: ['Generated columns cannot work with JSON', 'Use triggers for JSON extraction only', 'Create generated columns that extract and index specific JSON fields — pulling frequently queried values from JSONB into typed generated columns enables B-tree indexes and type-safe comparisons that are much faster than JSONB operators', 'JSONB columns are automatically indexed'], correctAnswer: 3, explanation: 'JSONB queries using -> and ->> operators cannot use standard B-tree indexes (they need GIN). By extracting frequently-queried JSON fields into generated columns, you get typed storage with B-tree indexing. This is especially valuable for fields used in WHERE clauses, JOIN conditions, or ORDER BY. The generated column stays automatically synchronized with the JSONB data, combining the flexibility of JSON with the performance of typed columns.', codeSnippet: "-- Extract JSON fields into generated columns:\nCREATE TABLE events (\n  id SERIAL PRIMARY KEY,\n  data JSONB NOT NULL,\n  -- Generated columns from JSON:\n  event_type TEXT GENERATED ALWAYS AS\n    (data->>'type') STORED,\n  user_id INT GENERATED ALWAYS AS\n    ((data->>'user_id')::INT) STORED,\n  created_at TIMESTAMPTZ GENERATED ALWAYS AS\n    ((data->>'timestamp')::TIMESTAMPTZ) STORED,\n  amount NUMERIC GENERATED ALWAYS AS\n    ((data->'payment'->>'amount')::NUMERIC) STORED\n);\n\n-- B-tree indexes on generated columns:\nCREATE INDEX ON events (event_type);\nCREATE INDEX ON events (user_id);\nCREATE INDEX ON events (created_at);\n\n-- Fast typed queries:\nSELECT * FROM events\nWHERE event_type = 'purchase'\n  AND user_id = 42\n  AND created_at > '2024-01-01'\nORDER BY created_at DESC;\n-- Uses B-tree indexes, not GIN JSONB scan", tags: ['advanced', 'generated-columns', 'jsonb', 'performance'] },
  { id: 'pg-advanced-l4-029', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Parallel Query', question: 'How do you implement parallel-safe custom functions?', options: ['All functions are parallel-safe by default', 'Use the PARALLEL keyword in function body', 'Mark functions with PARALLEL SAFE, PARALLEL RESTRICTED, or PARALLEL UNSAFE — SAFE functions can run in any parallel worker, RESTRICTED functions only in the leader process, and UNSAFE functions prevent the entire query from being parallelized', 'Parallel safety is determined by the query planner'], correctAnswer: 0, explanation: 'Function parallel safety must be explicitly declared. PARALLEL SAFE: the function has no side effects, does not access temporary tables, and produces the same result regardless of execution context. PARALLEL RESTRICTED: the function uses session state (e.g., temporary tables, current_setting) and can only run in the leader. PARALLEL UNSAFE: the function modifies data, uses advisory locks, or has unpredictable behavior. Incorrect marking can cause wrong results.', codeSnippet: "-- PARALLEL SAFE: pure computation\nCREATE FUNCTION normalize_email(email TEXT)\nRETURNS TEXT AS $$\nBEGIN\n  RETURN lower(trim(email));\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE;\n\n-- PARALLEL RESTRICTED: uses session state\nCREATE FUNCTION current_tenant()\nRETURNS INT AS $$\nBEGIN\n  RETURN current_setting('app.tenant_id')::INT;\nEND;\n$$ LANGUAGE plpgsql STABLE PARALLEL RESTRICTED;\n\n-- PARALLEL UNSAFE: modifies data\nCREATE FUNCTION log_access(table_name TEXT)\nRETURNS VOID AS $$\nBEGIN\n  INSERT INTO access_log VALUES (table_name, now());\nEND;\n$$ LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE;\n\n-- Check and fix safety:\nSELECT proname, proparallel FROM pg_proc\nWHERE proname = 'my_func';\n\nALTER FUNCTION my_func(INT) PARALLEL SAFE;", tags: ['advanced', 'parallel-query', 'parallel-safe', 'function-safety'] },
  { id: 'pg-advanced-l4-030', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Row-Level Security', question: 'What is the difference between permissive and restrictive RLS policies?', options: ['They are the same type of policy', 'Permissive policies deny access, restrictive policies allow it', 'Permissive policies (default) are combined with OR — any matching permissive policy grants access, while restrictive policies (AS RESTRICTIVE) are combined with AND — all restrictive policies must be satisfied, enabling layered security constraints', 'Restrictive policies override permissive policies completely'], correctAnswer: 1, explanation: 'Multiple permissive policies are OR-ed: if ANY permissive policy allows access, the row is visible. Multiple restrictive policies are AND-ed: ALL restrictive policies must allow access. The final check is: (any_permissive_match) AND (all_restrictive_match). Use permissive for granting access (e.g., users see their own data OR public data). Use restrictive for additional mandatory constraints (e.g., AND row is not archived AND row is in current fiscal year).', codeSnippet: "-- Permissive (default): combined with OR\nCREATE POLICY see_own ON documents\n  AS PERMISSIVE\n  USING (owner_id = current_user_id());\n\nCREATE POLICY see_public ON documents\n  AS PERMISSIVE\n  USING (is_public = TRUE);\n-- User sees rows where:\n-- owner_id = me OR is_public = TRUE\n\n-- Restrictive: combined with AND\nCREATE POLICY not_archived ON documents\n  AS RESTRICTIVE\n  USING (archived_at IS NULL);\n\nCREATE POLICY current_year ON documents\n  AS RESTRICTIVE\n  USING (extract(year from created_at) = extract(year from now()));\n\n-- Final check:\n-- (owner_id = me OR is_public)\n-- AND archived_at IS NULL\n-- AND year = current_year\n\n-- Restrictive policies add mandatory constraints\n-- that cannot be bypassed by permissive policies", tags: ['advanced', 'row-level-security', 'permissive', 'restrictive'] },
  { id: 'pg-advanced-l4-031', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'How do you use logical decoding for zero-downtime schema migrations?', options: ['Logical decoding is not related to migrations', 'Use pg_dump for zero-downtime migrations', 'Set up bidirectional logical replication between old and new database versions — migrate the schema on the new database, switch applications to the new database, and use logical decoding to keep data synchronized during the transition period', 'Zero-downtime migrations are impossible'], correctAnswer: 2, explanation: 'Logical replication enables blue-green database deployments: 1) Set up new database with updated schema. 2) Establish logical replication from old to new. 3) Apply schema changes on the new database (logical replication handles column differences). 4) Wait for replication to catch up. 5) Switch applications to the new database. 6) Briefly pause writes during the final switchover. This avoids long-running ALTER TABLE locks on the production database.', codeSnippet: "-- Old database: create publication\nCREATE PUBLICATION migration_pub FOR ALL TABLES;\n\n-- New database: subscribe and apply schema changes\nCREATE SUBSCRIPTION migration_sub\n  CONNECTION 'host=old-db dbname=prod'\n  PUBLICATION migration_pub;\n\n-- Wait for initial sync:\nSELECT * FROM pg_stat_subscription;\n-- srsubstate = 'r' (ready)\n\n-- Apply schema changes on new database:\nALTER TABLE orders ADD COLUMN new_field TEXT;\nCREATE INDEX CONCURRENTLY ...;\n\n-- Monitor lag:\nSELECT pg_size_pretty(\n  pg_wal_lsn_diff(\n    sent_lsn, replay_lsn\n  )\n) AS lag\nFROM pg_stat_replication;\n\n-- Switchover:\n-- 1. Stop writes to old database\n-- 2. Wait for replication to flush\n-- 3. Point applications to new database\n-- 4. Drop subscription and publication", tags: ['advanced', 'logical-decoding', 'zero-downtime', 'schema-migration'] },
  { id: 'pg-advanced-l4-032', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Background Workers', question: 'How does pg_cron implement background job scheduling?', options: ['pg_cron uses operating system cron', 'pg_cron stores jobs in configuration files', 'pg_cron registers a background worker process that wakes up every minute to check the cron.job table — matching jobs are executed as database connections within the PostgreSQL server process, supporting standard cron syntax for scheduling', 'pg_cron requires an external scheduler daemon'], correctAnswer: 3, explanation: 'pg_cron is implemented as a PostgreSQL background worker extension. It maintains a launcher process that checks the cron.job table periodically. When a job is due, it creates a background worker that connects to the specified database and executes the SQL. Jobs support standard 5-field cron syntax (minute, hour, day, month, weekday). pg_cron runs within PostgreSQL — no external infrastructure needed. It must be loaded in shared_preload_libraries.', codeSnippet: "-- Install pg_cron:\n-- postgresql.conf: shared_preload_libraries = 'pg_cron'\n-- Restart PostgreSQL\nCREATE EXTENSION pg_cron;\n\n-- Schedule a job (vacuum every night at 3 AM):\nSELECT cron.schedule(\n  'nightly-vacuum',\n  '0 3 * * *',\n  'VACUUM ANALYZE'\n);\n\n-- Refresh materialized view hourly:\nSELECT cron.schedule(\n  'refresh-mv',\n  '0 * * * *',\n  'REFRESH MATERIALIZED VIEW CONCURRENTLY mv_stats'\n);\n\n-- Run in a specific database:\nSELECT cron.schedule_in_database(\n  'cleanup',\n  '*/15 * * * *',\n  $$DELETE FROM logs WHERE ts < now() - interval '30 days'$$,\n  'production'\n);\n\n-- View scheduled jobs:\nSELECT * FROM cron.job;\n\n-- View job history:\nSELECT * FROM cron.job_run_details\nORDER BY start_time DESC LIMIT 10;", tags: ['advanced', 'background-workers', 'pg-cron', 'job-scheduling'] },
  { id: 'pg-advanced-l4-033', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'JIT Compilation', question: 'How do you monitor and diagnose JIT compilation performance?', options: ['JIT performance is not monitorable', 'Use system CPU profiling tools only', 'Use EXPLAIN (ANALYZE, BUFFERS) to see JIT timing breakdown, pg_stat_statements for aggregate JIT statistics across all queries, and track the ratio of JIT compilation time to execution time to identify queries where JIT adds overhead', 'Check PostgreSQL log files for JIT information'], correctAnswer: 0, explanation: 'JIT monitoring approaches: 1) EXPLAIN (ANALYZE) shows per-query JIT timing (generation, inlining, optimization, emission). 2) pg_stat_statements (PG 15+) tracks jit_functions, jit_generation_time, jit_inlining_time, jit_optimization_time, jit_emission_time across all executions. 3) Compare JIT time vs execution time: if JIT time exceeds query time, JIT is hurting. 4) The pg_jit_available() function checks if JIT is compiled into the server.', codeSnippet: "-- Per-query JIT diagnostics:\nEXPLAIN (ANALYZE, BUFFERS, FORMAT YAML)\nSELECT complex_query...;\n-- JIT:\n--   Functions: 42\n--   Options: Inlining true, Optimization true, Expressions true, Deforming true\n--   Timing:\n--     Generation: 3.5 ms\n--     Inlining: 15.2 ms\n--     Optimization: 28.1 ms\n--     Emission: 12.3 ms\n--     Total: 59.1 ms\n-- Execution Time: 45.0 ms\n-- JIT took LONGER than execution!\n\n-- Aggregate JIT stats (PG 15+):\nSELECT query,\n  calls,\n  round(mean_exec_time::numeric, 2) AS avg_ms,\n  jit_functions,\n  round(jit_generation_time::numeric, 2) AS gen_ms,\n  round(jit_inlining_time::numeric, 2) AS inline_ms,\n  round(jit_optimization_time::numeric, 2) AS opt_ms\nFROM pg_stat_statements\nWHERE jit_functions > 0\nORDER BY jit_generation_time + jit_inlining_time\n  + jit_optimization_time DESC\nLIMIT 10;", tags: ['advanced', 'jit-compilation', 'monitoring', 'explain-analyze'] },
  { id: 'pg-advanced-l4-034', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Custom Operators', question: 'How do you create custom range types with operators?', options: ['Range types are only for built-in types', 'Use BETWEEN for all range operations', 'Use CREATE TYPE name AS RANGE to define a custom range type — then define the required operators and operator class for the subtype, enabling range operations like containment (@>), overlap (&&), and intersection (*) on custom data types', 'Custom ranges require C extensions only'], correctAnswer: 1, explanation: 'PostgreSQL supports custom range types for any orderable data type. CREATE TYPE ... AS RANGE requires specifying the subtype (the element type), a subtype_diff function for GiST index efficiency, and a canonical function for discrete ranges. Once created, all range operators (@>, &&, *, +, -, etc.) and functions (lower, upper, isempty, etc.) work automatically. GiST and SP-GiST indexes support custom range types.', codeSnippet: "-- Custom range type for floats:\nCREATE TYPE floatrange AS RANGE (\n  subtype = float8,\n  subtype_diff = float8mi  -- built-in subtract\n);\n\n-- Use the custom range:\nSELECT floatrange(1.5, 3.7);\n-- [1.5,3.7)\n\n-- Range operations work automatically:\nSELECT floatrange(1.0, 5.0) @> 3.14;  -- true\nSELECT floatrange(1.0, 5.0) && floatrange(4.0, 8.0);  -- true\n\n-- Use in tables:\nCREATE TABLE temperature_ranges (\n  id SERIAL,\n  sensor TEXT,\n  normal_range floatrange,\n  EXCLUDE USING gist (sensor WITH =, normal_range WITH &&)\n);\n\n-- Custom range for IP addresses:\nCREATE TYPE inetrange AS RANGE (\n  subtype = inet\n);\n\nSELECT inetrange('192.168.1.0', '192.168.1.255')\n  @> '192.168.1.42'::inet; -- true", tags: ['advanced', 'custom-operators', 'range-types', 'create-type'] },
  { id: 'pg-advanced-l4-035', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Row-Level Security', question: 'How do you implement attribute-based access control (ABAC) with RLS?', options: ['ABAC requires an external policy engine', 'RLS only supports role-based access control', 'Implement ABAC by creating RLS policies that reference session variables, user attributes, resource attributes, and environmental conditions — using current_setting() for context, joining with authorization tables, and checking time/location conditions in the USING clause', 'ABAC is the same as RBAC'], correctAnswer: 2, explanation: 'ABAC uses attributes of the user (department, clearance level), resource (classification, owner), action (read, write), and environment (time, location) to make access decisions. RLS policies can implement ABAC by: 1) Setting user attributes as session variables. 2) Joining with authorization tables in the policy. 3) Checking resource attributes in the USING clause. 4) Adding environmental conditions (time of day, IP address). This is more flexible than simple role-based access.', codeSnippet: "-- User attributes in session:\nSET app.user_clearance = 'secret';\nSET app.user_department = 'engineering';\nSET app.user_country = 'US';\n\n-- ABAC policy: multi-attribute check\nCREATE POLICY abac_policy ON classified_docs\n  USING (\n    -- User clearance >= document classification\n    CASE current_setting('app.user_clearance')\n      WHEN 'top_secret' THEN TRUE\n      WHEN 'secret' THEN classification <= 'secret'\n      WHEN 'confidential' THEN classification <= 'confidential'\n      ELSE classification = 'unclassified'\n    END\n    -- AND user department matches\n    AND (department = current_setting('app.user_department')\n         OR department = 'public')\n    -- AND country restriction\n    AND (allowed_countries @> ARRAY[\n          current_setting('app.user_country')])\n    -- AND time-based access\n    AND (access_hours IS NULL\n         OR extract(hour from now())\n            BETWEEN (access_hours->>0)::INT\n            AND (access_hours->>1)::INT)\n  );", tags: ['advanced', 'row-level-security', 'abac', 'attribute-based'] },
  { id: 'pg-advanced-l4-036', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'How do you build a custom logical decoding output plugin?', options: ['Output plugins can be built in any language', 'Use PL/pgSQL for output plugins', 'Output plugins are written in C and implement callback functions for begin, change, commit, and other events — they are compiled as shared libraries and loaded by the replication slot, transforming WAL entries into the desired output format', 'Output plugins are configured in postgresql.conf'], correctAnswer: 3, explanation: 'Custom output plugins are C shared libraries that implement the LogicalDecodingOutputPlugin API. Key callbacks: startup_cb (initialization), begin_cb (transaction start), change_cb (row change), commit_cb (transaction commit), filter_by_origin_cb (origin filtering). The plugin registers itself with RegisterOutputPlugin. Build with pg_config for correct headers and flags. This is the mechanism used by pgoutput, test_decoding, and wal2json.', codeSnippet: "-- Output plugin is a C shared library:\n-- my_plugin.c\n\n/*\n#include \"postgres.h\"\n#include \"replication/logical.h\"\n#include \"replication/output_plugin.h\"\n\nstatic void\nmy_change_cb(LogicalDecodingContext *ctx,\n             ReorderBufferTXN *txn,\n             Relation relation,\n             ReorderBufferChange *change)\n{\n    // Format the change as desired\n    OutputPluginPrepareWrite(ctx, true);\n    appendStringInfo(ctx->out,\n        \"{\\\"table\\\":\\\"%s\\\",\\\"op\\\":\\\"%s\\\"}\",\n        RelationGetRelationName(relation),\n        change->action == REORDER_BUFFER_CHANGE_INSERT\n            ? \"INSERT\" : \"OTHER\");\n    OutputPluginWrite(ctx, true);\n}\n*/\n\n-- Build:\n-- gcc -shared -o my_plugin.so my_plugin.c\n--   $(pg_config --cflags) -I$(pg_config --includedir-server)\n\n-- Use:\nSELECT pg_create_logical_replication_slot(\n  'my_slot', 'my_plugin'\n);", tags: ['advanced', 'logical-decoding', 'custom-plugin', 'c-extension'] },
  { id: 'pg-advanced-l4-037', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Spatial Indexing', question: 'How do you implement multi-column spatial-temporal indexes?', options: ['Create separate indexes for space and time', 'Multi-column spatial indexes are not possible', 'Use the btree_gist extension to create a composite GiST index on both a geometry column and a timestamp/range column — this enables efficient queries that filter on both spatial and temporal dimensions simultaneously in a single index scan', 'Use a hash index combining space and time'], correctAnswer: 0, explanation: 'The btree_gist extension adds GiST support for scalar types (integer, timestamp, text, etc.), allowing them to be combined with native GiST types (geometry, range) in a single multi-column GiST index. This is critical for spatio-temporal queries where you filter on both location AND time. Without a composite index, PostgreSQL must scan one index and then filter, which is much slower than a single multi-dimensional index scan.', codeSnippet: "CREATE EXTENSION btree_gist;\n\n-- Composite spatial-temporal index:\nCREATE INDEX idx_events_spacetime\n  ON events USING gist (\n    location,           -- geometry column\n    occurred_at,        -- timestamp column (via btree_gist)\n    event_type          -- text column (via btree_gist)\n  );\n\n-- Efficient multi-dimensional query:\nSELECT * FROM events\nWHERE ST_DWithin(location, my_point, 1000)\n  AND occurred_at BETWEEN '2024-01-01' AND '2024-03-01'\n  AND event_type = 'accident';\n-- Single index scan covers all three conditions!\n\n-- Exclusion constraint (no overlapping bookings):\nCREATE TABLE room_bookings (\n  room_id INT,\n  booked_range TSTZRANGE,\n  EXCLUDE USING gist (\n    room_id WITH =,\n    booked_range WITH &&\n  )\n);\n-- Prevents double-booking same room", tags: ['advanced', 'spatial-indexing', 'btree-gist', 'composite-index'] },
  { id: 'pg-advanced-l4-038', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Generated Columns', question: 'How do you use generated columns for data validation patterns?', options: ['Generated columns cannot be used for validation', 'Use CHECK constraints instead', 'Create generated columns that compute validation flags or normalized values — combined with CHECK constraints on the generated columns, this enables complex validation logic that would be too complex for a single CHECK expression', 'Use triggers for all validation'], correctAnswer: 1, explanation: 'Generated columns can compute intermediate values that make validation clearer. Instead of a complex CHECK constraint, compute a validation flag in a generated column and apply a simple CHECK on it. This also makes the validation result queryable and debuggable. Common patterns: computing a checksum digit for ID validation, normalizing formats for consistency checks, deriving status from multiple fields for state machine validation.', codeSnippet: "-- Validation with generated columns:\nCREATE TABLE invoices (\n  id SERIAL PRIMARY KEY,\n  subtotal NUMERIC NOT NULL,\n  tax NUMERIC NOT NULL,\n  total NUMERIC NOT NULL,\n  -- Validate total matches:\n  is_total_valid BOOLEAN GENERATED ALWAYS AS (\n    abs(total - (subtotal + tax)) < 0.01\n  ) STORED,\n  -- Normalized phone:\n  phone_raw TEXT,\n  phone_normalized TEXT GENERATED ALWAYS AS (\n    regexp_replace(phone_raw, '[^0-9]', '', 'g')\n  ) STORED,\n  -- Computed status:\n  due_date DATE,\n  paid_at TIMESTAMPTZ,\n  status TEXT GENERATED ALWAYS AS (\n    CASE\n      WHEN paid_at IS NOT NULL THEN 'paid'\n      WHEN due_date < CURRENT_DATE THEN 'overdue'\n      ELSE 'pending'\n    END\n  ) STORED\n);\n\n-- Simple CHECK on generated column:\nALTER TABLE invoices\n  ADD CONSTRAINT valid_total CHECK (is_total_valid);\n\n-- Index on generated status:\nCREATE INDEX ON invoices (status);", tags: ['advanced', 'generated-columns', 'validation', 'check-constraints'] },
  { id: 'pg-advanced-l4-039', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Parallel Query', question: 'How does parallel query work with partitioned tables?', options: ['Partitioned tables cannot use parallel queries', 'Each partition always gets its own worker', 'PostgreSQL can perform partition-wise parallel operations — Append nodes can run partition scans in parallel, and partition-wise joins/aggregates allow each partition to be processed by a separate worker, controlled by enable_partitionwise_join and enable_partitionwise_aggregate', 'Parallel queries ignore the partition structure'], correctAnswer: 2, explanation: 'Parallel query and partitioning interact in several ways: 1) Parallel Append scans multiple partitions concurrently. 2) Partition-wise join (enable_partitionwise_join) allows joins to happen per-partition in parallel. 3) Partition-wise aggregate (enable_partitionwise_aggregate) allows aggregation per-partition before combining. These are disabled by default because planning time increases with many partitions. Enable them for partition-heavy analytical queries.', codeSnippet: "-- Enable partition-wise operations:\nSET enable_partitionwise_join = on;\nSET enable_partitionwise_aggregate = on;\nSET enable_parallel_append = on;\n\n-- Parallel scan across partitions:\nEXPLAIN (ANALYZE)\nSELECT COUNT(*) FROM partitioned_events\nWHERE event_date > '2024-01-01';\n-- Gather\n--   Workers: 4\n--   -> Parallel Append\n--     -> Parallel Seq Scan on events_2024_q1\n--     -> Parallel Seq Scan on events_2024_q2\n--     -> ...\n\n-- Partition-wise aggregate:\nSELECT date_trunc('month', event_date), COUNT(*)\nFROM partitioned_events\nGROUP BY 1;\n-- Each partition aggregates independently\n-- Then results are combined\n\n-- Partition-wise join:\nSELECT * FROM orders_partitioned o\nJOIN customers_partitioned c\n  ON o.region = c.region AND o.customer_id = c.id;\n-- Join happens per-partition if both\n-- are partitioned on 'region'", tags: ['advanced', 'parallel-query', 'partitioning', 'partition-wise'] },
  { id: 'pg-advanced-l4-040', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Custom Operators', question: 'How do you create domain-specific query languages using custom operators?', options: ['PostgreSQL only supports SQL syntax', 'Use text parsing functions instead', 'Define a set of custom operators with intuitive symbols that implement domain-specific logic — combined with custom types and operator classes, this creates a domain-specific sublanguage within SQL that reads naturally for domain experts', 'Custom query languages require a parser extension'], correctAnswer: 3, explanation: 'Custom types and operators can create expressive domain-specific query interfaces within SQL. For example, a genomics database might define a DNA type with operators for sequence matching (@~), complement (~), and alignment (<=>). A financial database might define money operators for currency conversion (@>$). This approach leverages PostgreSQL extensibility to make queries readable for domain experts while maintaining full SQL compatibility and index support.', codeSnippet: "-- Domain: time interval calculations\nCREATE TYPE timespan AS (\n  start_ts TIMESTAMPTZ,\n  end_ts TIMESTAMPTZ\n);\n\n-- Overlap operator:\nCREATE FUNCTION timespan_overlaps(a timespan, b timespan)\nRETURNS BOOLEAN AS $$\n  SELECT a.start_ts < b.end_ts AND b.start_ts < a.end_ts;\n$$ LANGUAGE sql IMMUTABLE;\n\nCREATE OPERATOR && (\n  FUNCTION = timespan_overlaps,\n  LEFTARG = timespan,\n  RIGHTARG = timespan,\n  COMMUTATOR = &&\n);\n\n-- Duration operator:\nCREATE FUNCTION timespan_duration(t timespan)\nRETURNS INTERVAL AS $$\n  SELECT t.end_ts - t.start_ts;\n$$ LANGUAGE sql IMMUTABLE;\n\nCREATE OPERATOR # (\n  FUNCTION = timespan_duration,\n  RIGHTARG = timespan\n);\n\n-- Natural domain queries:\nSELECT * FROM meetings m1, meetings m2\nWHERE m1.span && m2.span  -- overlapping meetings\n  AND m1.id < m2.id;\n\nSELECT name, # span AS duration FROM meetings;", tags: ['advanced', 'custom-operators', 'domain-specific', 'extensibility'] },
  { id: 'pg-advanced-l4-041', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Row-Level Security', question: 'How do you handle RLS performance optimization?', options: ['RLS has zero performance impact', 'RLS always requires a full table scan', 'Ensure RLS policy expressions can use indexes — policies that reference indexed columns with simple equality or range conditions integrate with query optimization, while policies using functions or complex expressions may force sequential scans', 'Use materialized views to cache RLS results'], correctAnswer: 0, explanation: 'RLS performance depends on how the policy USING expression interacts with the query planner. The policy condition is appended to the query WHERE clause, so it benefits from the same index optimizations. Key tips: 1) Index the columns referenced in policies (e.g., tenant_id). 2) Use simple expressions (equality, range) that the planner can optimize. 3) Avoid volatile functions in policies. 4) Use EXPLAIN to verify index usage. 5) Consider partial indexes matching common policy conditions.', codeSnippet: "-- Well-optimized RLS:\n-- 1. Simple indexed expression:\nCREATE INDEX ON orders (tenant_id);\n\nCREATE POLICY tenant_policy ON orders\n  USING (tenant_id = current_setting('app.tenant_id')::INT);\n-- Planner combines with query:\n-- WHERE tenant_id = 42 AND status = 'active'\n-- Uses index on (tenant_id, status)\n\n-- 2. Verify with EXPLAIN:\nSET app.tenant_id = '42';\nEXPLAIN (ANALYZE)\nSELECT * FROM orders WHERE status = 'active';\n-- Index Scan using idx_orders_tenant_status\n--   Index Cond: (tenant_id = 42) AND (status = 'active')\n\n-- 3. Partial index matching policy:\nCREATE INDEX idx_active_orders\n  ON orders (customer_id)\n  WHERE tenant_id = 42;\n-- Only useful for tenant 42, but very fast\n\n-- 4. Composite index for policy + query:\nCREATE INDEX ON orders (tenant_id, status, created_at);", tags: ['advanced', 'row-level-security', 'performance', 'indexing'] },
  { id: 'pg-advanced-l4-042', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'How do you implement conflict resolution in logical replication?', options: ['Conflicts never occur in logical replication', 'PostgreSQL handles all conflicts automatically', 'Conflicts (duplicate keys, missing rows) cause the subscriber to stop — handle them by creating conflict resolution triggers on the subscriber, using ON CONFLICT clauses in the apply process, or implementing custom conflict handlers in application code', 'Use physical replication to avoid conflicts'], correctAnswer: 1, explanation: 'Logical replication conflicts occur when: 1) INSERT duplicates an existing key. 2) UPDATE/DELETE targets a non-existent row. 3) Constraint violations. By default, conflicts stop replication. Solutions: 1) Ensure non-overlapping key ranges between publisher and subscriber. 2) Create BEFORE triggers on subscriber tables that handle conflicts (e.g., skip or merge). 3) Use pg_replication_origin to track changes and prevent loops. 4) Monitor pg_stat_subscription for errors.', codeSnippet: "-- Monitor for conflicts:\nSELECT subname, received_lsn, latest_end_lsn,\n  last_msg_send_time, last_msg_receipt_time\nFROM pg_stat_subscription;\n\n-- Check for errors in subscriber log:\n-- LOG: logical replication apply worker for subscription \"my_sub\"\n--   has started\n-- ERROR: duplicate key value violates unique constraint\n\n-- Conflict handler trigger on subscriber:\nCREATE FUNCTION handle_replication_conflict()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- On conflict, update existing row:\n  IF TG_OP = 'INSERT' THEN\n    BEGIN\n      RETURN NEW;\n    EXCEPTION WHEN unique_violation THEN\n      UPDATE pg_temp_table SET\n        col1 = NEW.col1, col2 = NEW.col2\n      WHERE id = NEW.id;\n      RETURN NULL; -- skip the INSERT\n    END;\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Skip conflicting transactions:\nALTER SUBSCRIPTION my_sub\n  DISABLE;\n-- Fix data, then:\nALTER SUBSCRIPTION my_sub\n  ENABLE;", tags: ['advanced', 'logical-decoding', 'conflict-resolution', 'replication'] },
  { id: 'pg-advanced-l4-043', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'JIT Compilation', question: 'How does JIT compilation interact with expression evaluation in PostgreSQL?', options: ['JIT compiles entire SQL statements', 'JIT only optimizes sorting operations', 'JIT compiles three main components: expression evaluation (WHERE clauses, projections, aggregations), tuple deforming (extracting column values from on-disk format), and function bodies — converting interpreted evaluation into native machine code via LLVM', 'JIT replaces the query planner'], correctAnswer: 2, explanation: 'PostgreSQL JIT compiles: 1) Expression evaluation: WHERE conditions, target list computations, aggregate transitions. The interpreted expression evaluator is replaced with compiled native code. 2) Tuple deforming: extracting column values from the on-disk tuple format, which involves navigating variable-length fields. JIT generates code specialized for the actual table schema. 3) These are controlled independently and benefit different query types. Complex expressions benefit most from JIT.', codeSnippet: "-- Expression-heavy query (benefits from JIT):\nEXPLAIN (ANALYZE, VERBOSE)\nSELECT\n  CASE WHEN a > 100 THEN a * 1.1\n       WHEN b BETWEEN 50 AND 200 THEN b * 0.9\n       ELSE c + d * e END AS computed,\n  sqrt(a*a + b*b) AS distance,\n  regexp_replace(name, '[^a-z]', '', 'gi') AS clean_name\nFROM large_table\nWHERE a + b > c * 2\n  AND length(name) > 5\n  AND status IN ('active', 'pending', 'review');\n\n-- JIT output:\n-- JIT:\n--   Functions: 8 (expressions compiled)\n--   Options:\n--     Inlining: true (function bodies inlined)\n--     Optimization: true (LLVM optimization passes)\n--     Expressions: true (WHERE + SELECT compiled)\n--     Deforming: true (tuple access compiled)\n\n-- Deforming benefits wide tables:\nSELECT col50, col100 FROM very_wide_table;\n-- JIT generates efficient code to skip to col50/col100\n-- instead of interpreting each column offset", tags: ['advanced', 'jit-compilation', 'expression-evaluation', 'llvm'] },
  { id: 'pg-advanced-l4-044', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Spatial Indexing', question: 'How do you implement spatial partitioning for PostGIS data?', options: ['PostGIS data cannot be partitioned', 'Use hash partitioning on geometry columns', 'Partition spatial data by geographic region using list partitioning on a region column, or by spatial grid cells — this enables partition pruning for spatially-filtered queries and allows independent maintenance of geographic data subsets', 'Use table inheritance for spatial partitioning only'], correctAnswer: 3, explanation: 'Spatial partitioning strategies: 1) List partition by region/country (derived column or trigger-assigned). 2) Hash partition on a spatial hash (geohash, S2 cell, H3 hex). 3) Range partition on coordinates (latitude bands). Each partition has its own spatial index, which is smaller and faster than a single large index. Partition pruning works when the query includes the partition key. This is essential for multi-billion row spatial datasets.', codeSnippet: "-- Partition by region:\nCREATE TABLE spatial_events (\n  id BIGSERIAL,\n  location GEOMETRY(Point, 4326),\n  region TEXT,\n  data JSONB\n) PARTITION BY LIST (region);\n\nCREATE TABLE events_north_america\n  PARTITION OF spatial_events\n  FOR VALUES IN ('NA');\nCREATE TABLE events_europe\n  PARTITION OF spatial_events\n  FOR VALUES IN ('EU');\nCREATE TABLE events_asia\n  PARTITION OF spatial_events\n  FOR VALUES IN ('AS');\n\n-- Each partition gets its own spatial index:\nCREATE INDEX ON events_north_america USING gist (location);\nCREATE INDEX ON events_europe USING gist (location);\nCREATE INDEX ON events_asia USING gist (location);\n\n-- Partition-pruned query:\nSELECT * FROM spatial_events\nWHERE region = 'EU'\n  AND ST_DWithin(location::geography,\n    ST_MakePoint(13.4, 52.5)::geography, 1000);\n-- Only scans events_europe partition!", tags: ['advanced', 'spatial-indexing', 'partitioning', 'spatial-data'] },
  { id: 'pg-advanced-l4-045', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Generated Columns', question: 'How do you migrate from triggers to generated columns?', options: ['Triggers and generated columns cannot coexist', 'Drop the trigger and add a generated column in one ALTER TABLE', 'Add the generated column, verify it matches the trigger output, then drop the trigger — this requires the generated expression to be IMMUTABLE and replicate exactly what the trigger computed, with careful testing during the transition period', 'Generated columns automatically replace matching triggers'], correctAnswer: 0, explanation: 'Migrating from trigger-maintained columns to generated columns: 1) Create the generated column (may require adding as a new column). 2) Verify the generated values match the trigger-computed values for all rows. 3) Drop the trigger. 4) If column names must match, rename the old column, rename the generated column, then drop the old column. Limitations: the generated expression must be IMMUTABLE (no now(), no subqueries), so not all trigger logic can be migrated.', codeSnippet: "-- Current: trigger maintains full_name\nCREATE FUNCTION set_full_name()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.full_name := NEW.first_name || ' ' || NEW.last_name;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Step 1: Add generated column (new name):\nALTER TABLE users ADD COLUMN full_name_gen TEXT\n  GENERATED ALWAYS AS (\n    first_name || ' ' || last_name\n  ) STORED;\n\n-- Step 2: Verify match:\nSELECT count(*)\nFROM users\nWHERE full_name IS DISTINCT FROM full_name_gen;\n-- Should be 0\n\n-- Step 3: Drop trigger:\nDROP TRIGGER trg_set_full_name ON users;\n\n-- Step 4: Swap columns:\nALTER TABLE users DROP COLUMN full_name;\nALTER TABLE users RENAME COLUMN full_name_gen TO full_name;\n\n-- Step 5: Recreate indexes on new column:\nCREATE INDEX ON users (full_name);", tags: ['advanced', 'generated-columns', 'migration', 'trigger-replacement'] },
  { id: 'pg-advanced-l4-046', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Parallel Query', question: 'How do you use parallel CREATE INDEX for faster index building?', options: ['CREATE INDEX is always single-threaded', 'Use CREATE INDEX PARALLEL to enable parallelism', 'ALTER TABLE SET (parallel_workers = N) controls the number of workers for CREATE INDEX — PostgreSQL automatically uses parallel workers for B-tree index creation when the table is large enough, significantly reducing build time for large tables', 'Only GiST indexes support parallel creation'], correctAnswer: 1, explanation: 'Parallel B-tree index creation (added in PG 11) uses multiple workers to sort data in parallel, then merge the sorted runs. The number of workers is determined by: 1) parallel_workers table storage parameter, 2) max_parallel_maintenance_workers (default 2), 3) Table size relative to min_parallel_table_scan_size. CONCURRENTLY index builds also benefit from parallelism (PG 12+). GiST, GIN, and other index types do not yet support parallel building.', codeSnippet: "-- Set maintenance parallelism:\nSET max_parallel_maintenance_workers = 4;\n\n-- Per-table parallel workers:\nALTER TABLE large_table SET (parallel_workers = 4);\n\n-- Create index (automatically parallel):\nCREATE INDEX idx_large ON large_table (column_a);\n-- Uses 4 parallel workers for sorting\n\n-- CONCURRENTLY also benefits:\nCREATE INDEX CONCURRENTLY idx_large_conc\n  ON large_table (column_b);\n\n-- Monitor progress:\nSELECT phase, blocks_done, blocks_total,\n  tuples_done, tuples_total\nFROM pg_stat_progress_create_index;\n\n-- Compare timing:\n-- Without parallel: 120 seconds\nSET max_parallel_maintenance_workers = 0;\nCREATE INDEX idx_serial ON t (col);\n\n-- With parallel (4 workers): ~35 seconds\nSET max_parallel_maintenance_workers = 4;\nCREATE INDEX idx_parallel ON t (col);", tags: ['advanced', 'parallel-query', 'create-index', 'maintenance'] },
  { id: 'pg-advanced-l4-047', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'How do you implement message-based logical decoding with pg_logical_emit_message?', options: ['Logical decoding only captures DML changes', 'Use NOTIFY for message-based decoding', 'Use pg_logical_emit_message(transactional, prefix, content) to inject custom messages into the WAL stream — these messages appear in the logical decoding output alongside regular changes, enabling application-level events to be captured by CDC pipelines', 'Messages require a custom WAL record type'], correctAnswer: 2, explanation: 'pg_logical_emit_message() writes a custom message into the WAL that appears in logical decoding output. The transactional parameter controls whether the message is part of the current transaction (delivered with COMMIT) or non-transactional (delivered immediately). The prefix parameter is used for filtering. This enables injecting application-level events (like "deployment started" or "cache invalidated") into the CDC stream alongside data changes.', codeSnippet: "-- Transactional message (part of transaction):\nSELECT pg_logical_emit_message(\n  TRUE,           -- transactional\n  'app_events',   -- prefix for filtering\n  '{\"event\": \"order_completed\", \"order_id\": 12345}'\n);\n\n-- Non-transactional (immediate delivery):\nSELECT pg_logical_emit_message(\n  FALSE,\n  'system',\n  '{\"event\": \"deployment_v2.5\", \"ts\": \"2024-01-15\"}'\n);\n\n-- Messages appear in decoding output:\nSELECT * FROM pg_logical_slot_get_changes(\n  'my_slot', NULL, NULL\n);\n-- xid | data\n-- 100 | BEGIN\n-- 100 | table orders: INSERT ...\n-- 100 | message: prefix=app_events; content={...}\n-- 100 | COMMIT\n\n-- Use in triggers for enriched CDC:\nCREATE FUNCTION emit_event()\nRETURNS TRIGGER AS $$\nBEGIN\n  PERFORM pg_logical_emit_message(TRUE, 'events',\n    json_build_object('type', TG_OP, 'table', TG_TABLE_NAME,\n      'id', NEW.id)::TEXT);\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'logical-decoding', 'custom-messages', 'wal-events'] },
  { id: 'pg-advanced-l4-048', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Row-Level Security', question: 'How do you implement RLS for partitioned tables?', options: ['RLS does not work with partitioned tables', 'Define policies on each partition separately', 'Enable RLS and define policies on the parent partitioned table — the policies automatically apply to all partitions, providing consistent security across the entire partition hierarchy without duplicating policy definitions', 'Use views over partitioned tables for RLS'], correctAnswer: 3, explanation: 'RLS on partitioned tables works by defining policies on the parent table. All partitions inherit the RLS enablement and policies. This is consistent with how other table-level features (triggers, constraints) work with declarative partitioning. The policies are evaluated per-partition during query execution. Partition pruning still works alongside RLS — the planner combines partition elimination with RLS filtering for optimal performance.', codeSnippet: "-- Partitioned table:\nCREATE TABLE tenant_data (\n  id BIGSERIAL,\n  tenant_id INT NOT NULL,\n  data JSONB,\n  created_at DATE NOT NULL\n) PARTITION BY RANGE (created_at);\n\nCREATE TABLE tenant_data_2024_q1\n  PARTITION OF tenant_data\n  FOR VALUES FROM ('2024-01-01') TO ('2024-04-01');\n\nCREATE TABLE tenant_data_2024_q2\n  PARTITION OF tenant_data\n  FOR VALUES FROM ('2024-04-01') TO ('2024-07-01');\n\n-- RLS on parent (applies to all partitions):\nALTER TABLE tenant_data ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY tenant_isolation ON tenant_data\n  USING (tenant_id = current_setting('app.tenant_id')::INT)\n  WITH CHECK (tenant_id = current_setting('app.tenant_id')::INT);\n\n-- Both partition pruning AND RLS work:\nSET app.tenant_id = '42';\nSELECT * FROM tenant_data\nWHERE created_at = '2024-02-15';\n-- Only scans 2024_q1 (pruning)\n-- AND only returns tenant 42 rows (RLS)", tags: ['advanced', 'row-level-security', 'partitioning', 'multi-tenant'] },
  { id: 'pg-advanced-l4-049', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Generated Columns', question: 'How do you use generated columns for efficient computed aggregates?', options: ['Generated columns cannot help with aggregates', 'Use materialized views for pre-computed aggregates', 'Create generated columns that pre-compute values needed for aggregation — such as extracting date parts, computing categories, or normalizing values, allowing GROUP BY on generated columns with B-tree index support for faster aggregation queries', 'Use window functions instead'], correctAnswer: 0, explanation: 'Generated columns can pre-compute values frequently used in GROUP BY, WHERE, or ORDER BY clauses. For example, extracting the month from a timestamp, computing a price tier, or categorizing text. Since these are STORED and can be indexed, aggregation queries that group by these computed values can use index scans instead of computing the expression for every row. This is especially effective for time-series data grouped by date parts.', codeSnippet: "-- Pre-compute aggregation keys:\nCREATE TABLE sales (\n  id SERIAL PRIMARY KEY,\n  sold_at TIMESTAMPTZ NOT NULL,\n  amount NUMERIC NOT NULL,\n  product_id INT NOT NULL,\n  -- Generated aggregation helpers:\n  sale_month DATE GENERATED ALWAYS AS (\n    date_trunc('month', sold_at)::DATE\n  ) STORED,\n  sale_year INT GENERATED ALWAYS AS (\n    extract(year from sold_at)::INT\n  ) STORED,\n  amount_tier TEXT GENERATED ALWAYS AS (\n    CASE\n      WHEN amount < 10 THEN 'small'\n      WHEN amount < 100 THEN 'medium'\n      WHEN amount < 1000 THEN 'large'\n      ELSE 'enterprise'\n    END\n  ) STORED\n);\n\n-- Index for aggregation:\nCREATE INDEX ON sales (sale_month, product_id);\nCREATE INDEX ON sales (amount_tier);\n\n-- Fast aggregation:\nSELECT sale_month, SUM(amount), COUNT(*)\nFROM sales\nGROUP BY sale_month\nORDER BY sale_month;\n-- Uses index scan, no expression computation", tags: ['advanced', 'generated-columns', 'aggregation', 'performance'] },
  { id: 'pg-advanced-l4-050', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Parallel Query', question: 'How do you implement parallel-safe aggregation with partial and combine steps?', options: ['All aggregates automatically support parallel execution', 'Parallel aggregation requires custom C code', 'Enable parallel aggregation by providing a combinefunc that merges partial aggregate states from different workers — each worker computes a partial result using sfunc, and the leader combines partials using combinefunc, with optional serialfunc/deserialfunc for cross-process state transfer', 'Use PARALLEL keyword in the aggregate definition'], correctAnswer: 1, explanation: 'Parallel aggregation works in three phases: 1) Each worker computes a partial aggregate state by processing a subset of rows with sfunc. 2) Partial states are sent to the leader (serialized if needed). 3) The leader combines partial states using combinefunc. For this to work, the aggregate needs: combinefunc (merge two states), optionally serialfunc/deserialfunc (for cross-process transfer), and PARALLEL SAFE marking. Built-in aggregates like SUM, COUNT, AVG already support this.', codeSnippet: "-- Parallel-safe custom aggregate:\nCREATE FUNCTION my_avg_sfunc(state NUMERIC[], val NUMERIC)\nRETURNS NUMERIC[] AS $$\nBEGIN\n  RETURN ARRAY[state[1] + val, state[2] + 1];\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE;\n\nCREATE FUNCTION my_avg_combine(\n  state1 NUMERIC[], state2 NUMERIC[]\n) RETURNS NUMERIC[] AS $$\nBEGIN\n  RETURN ARRAY[\n    state1[1] + state2[1],  -- combine sums\n    state1[2] + state2[2]   -- combine counts\n  ];\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE;\n\nCREATE FUNCTION my_avg_ffunc(state NUMERIC[])\nRETURNS NUMERIC AS $$\nBEGIN\n  IF state[2] = 0 THEN RETURN NULL; END IF;\n  RETURN state[1] / state[2];\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE;\n\nCREATE AGGREGATE my_avg(NUMERIC) (\n  sfunc = my_avg_sfunc,\n  stype = NUMERIC[],\n  finalfunc = my_avg_ffunc,\n  combinefunc = my_avg_combine,\n  initcond = '{0,0}',\n  parallel = safe\n);", tags: ['advanced', 'parallel-query', 'parallel-aggregation', 'combinefunc'] },
  { id: 'pg-advanced-l4-051', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Custom Operators', question: 'How do you implement fuzzy comparison operators for custom types?', options: ['Fuzzy comparison is only possible with pg_trgm', 'Use LIKE for all fuzzy comparisons', 'Create custom operators that implement approximate matching logic — such as a ~= operator for "approximately equal" that considers a tolerance range, enabling domain-specific fuzzy matching with proper index support through custom operator classes', 'Fuzzy operators require machine learning'], correctAnswer: 2, explanation: 'Custom fuzzy operators implement domain-specific approximate matching. For numeric types, this might be "within 5% tolerance". For text, it might be edit distance or phonetic matching. For temporal data, it might be "within the same hour". These operators can be backed by GiST or SP-GiST indexes for efficient lookups. The key is defining proper selectivity estimators so the planner can make good decisions about when to use the operator with indexes.', codeSnippet: "-- Approximate equality for measurements:\nCREATE FUNCTION approx_equal(\n  a NUMERIC, b NUMERIC, tolerance NUMERIC DEFAULT 0.05\n) RETURNS BOOLEAN AS $$\nBEGIN\n  RETURN abs(a - b) <= abs(a) * tolerance;\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE;\n\nCREATE OPERATOR ~= (\n  FUNCTION = approx_equal,\n  LEFTARG = NUMERIC,\n  RIGHTARG = NUMERIC,\n  COMMUTATOR = ~=\n);\n\n-- Usage:\nSELECT * FROM measurements\nWHERE value ~= 100.0;\n-- Finds values within 5% of 100 (95-105)\n\n-- Phonetic matching operator:\nCREATE FUNCTION sounds_like(a TEXT, b TEXT)\nRETURNS BOOLEAN AS $$\nBEGIN\n  RETURN soundex(a) = soundex(b)\n      OR metaphone(a, 4) = metaphone(b, 4);\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE;\n\nCREATE OPERATOR |~| (\n  FUNCTION = sounds_like,\n  LEFTARG = TEXT,\n  RIGHTARG = TEXT,\n  COMMUTATOR = |~|\n);\n\nSELECT * FROM contacts\nWHERE name |~| 'Smith'; -- finds Smyth, etc.", tags: ['advanced', 'custom-operators', 'fuzzy-matching', 'approximate'] },
  { id: 'pg-advanced-l4-052', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'How do you use logical decoding for cross-database synchronization?', options: ['Logical decoding only works within one database', 'Use pg_dump for synchronization', 'Set up logical replication with publications and subscriptions between databases — the publisher streams changes from selected tables, and the subscriber applies them, keeping databases synchronized in near-real-time with configurable table and column filtering', 'Cross-database sync requires physical replication'], correctAnswer: 3, explanation: 'Logical replication enables cross-database synchronization: 1) Different PostgreSQL versions (e.g., 14 to 16). 2) Different schemas (column differences handled by name matching). 3) Selective replication (specific tables/columns). 4) Different index strategies on subscriber. 5) Data consolidation from multiple publishers to one subscriber. Limitations: DDL is not replicated (schema changes must be applied manually), sequences are not replicated, and large objects are not replicated.', codeSnippet: "-- Publisher (source database):\nCREATE PUBLICATION sync_pub\n  FOR TABLE users, orders, products;\n\n-- Subscriber (target database):\nCREATE SUBSCRIPTION sync_sub\n  CONNECTION 'host=publisher port=5432 dbname=source_db'\n  PUBLICATION sync_pub\n  WITH (\n    copy_data = true,        -- initial data copy\n    create_slot = true,      -- create replication slot\n    synchronous_commit = off -- async for performance\n  );\n\n-- Monitor synchronization:\nSELECT subname, received_lsn, latest_end_lsn,\n  last_msg_send_time, last_msg_receipt_time\nFROM pg_stat_subscription;\n\n-- Multiple publishers to one subscriber:\nCREATE SUBSCRIPTION sub_from_db1\n  CONNECTION 'host=db1 dbname=prod'\n  PUBLICATION pub1;\n\nCREATE SUBSCRIPTION sub_from_db2\n  CONNECTION 'host=db2 dbname=prod'\n  PUBLICATION pub2;", tags: ['advanced', 'logical-decoding', 'synchronization', 'cross-database'] },
  { id: 'pg-advanced-l4-053', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Background Workers', question: 'How do you monitor and manage background worker processes?', options: ['Background workers are invisible to monitoring', 'Use operating system tools only', 'Monitor background workers through pg_stat_activity (backend_type column), control them via extension-specific interfaces, and manage the total count with max_worker_processes — each worker appears as a backend in system views with its own PID and state', 'Background workers cannot be managed after startup'], correctAnswer: 0, explanation: 'Background worker monitoring: 1) pg_stat_activity shows all backends including workers (backend_type = background worker). 2) Workers have their own PIDs visible in system views. 3) Extension-specific management (pg_cron has cron.job, pg_partman has part.config). 4) max_worker_processes limits total workers. 5) Workers can be signaled (pg_terminate_backend). 6) Crashed workers are restarted by the postmaster (configurable). 7) Log output is mixed with regular PostgreSQL logs.', codeSnippet: "-- View all background workers:\nSELECT pid, backend_type, application_name,\n  state, wait_event_type, wait_event, query\nFROM pg_stat_activity\nWHERE backend_type = 'background worker';\n\n-- Worker process types:\n-- logical replication launcher\n-- logical replication worker\n-- parallel worker\n-- pg_cron scheduler\n-- autovacuum launcher\n-- autovacuum worker\n\n-- Resource limits:\nSHOW max_worker_processes;     -- total workers (default 8)\nSHOW max_parallel_workers;     -- for parallel queries\nSHOW max_logical_replication_workers; -- for logical rep\n\n-- Terminate a stuck worker:\nSELECT pg_terminate_backend(pid)\nFROM pg_stat_activity\nWHERE backend_type = 'background worker'\n  AND application_name = 'stuck_worker';\n\n-- Check worker memory usage:\nSELECT pid, backend_type,\n  pg_size_pretty(backend_memory_contexts_bytes)\nFROM pg_stat_activity\nWHERE backend_type = 'background worker';", tags: ['advanced', 'background-workers', 'monitoring', 'pg-stat-activity'] },
  { id: 'pg-advanced-l4-054', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Spatial Indexing', question: 'How do you implement k-nearest-neighbor (KNN) search efficiently with PostGIS?', options: ['Use ST_Distance with ORDER BY and LIMIT', 'KNN requires a separate search engine', 'Use the <-> distance operator with ORDER BY and a GiST index — PostgreSQL implements true KNN index scanning where the index returns results in distance order without computing distance for every row, providing sub-millisecond nearest-neighbor queries on millions of points', 'Sort all results by distance in application code'], correctAnswer: 1, explanation: 'The <-> operator with GiST index enables true KNN (k-nearest-neighbor) index scan. Unlike ST_Distance + ORDER BY + LIMIT (which computes distance for ALL rows then sorts), KNN index scan traverses the GiST tree in distance order, returning only the needed K nearest results. This is orders of magnitude faster for "find nearest N" queries. Combine with LATERAL for per-row nearest-neighbor joins. The <#> operator gives centroid-based distance for polygons.', codeSnippet: "-- Efficient KNN with GiST index:\nCREATE INDEX idx_location_gist\n  ON places USING gist (location);\n\n-- Find 5 nearest places (uses KNN index scan):\nSELECT name,\n  ST_Distance(\n    location::geography,\n    ST_MakePoint(-73.985, 40.748)::geography\n  ) AS distance_m\nFROM places\nORDER BY location <-> ST_MakePoint(-73.985, 40.748)::geometry\nLIMIT 5;\n-- Index Scan (KNN) — sub-millisecond!\n\n-- Nearest-neighbor join (for each school, find nearest hospital):\nSELECT s.name AS school,\n  h.name AS hospital,\n  h.dist\nFROM schools s\nCROSS JOIN LATERAL (\n  SELECT name,\n    ST_Distance(location::geography, s.location::geography) AS dist\n  FROM hospitals\n  ORDER BY location <-> s.location\n  LIMIT 1\n) h;\n-- Uses KNN index for each school row", tags: ['advanced', 'spatial-indexing', 'knn', 'nearest-neighbor'] },
  { id: 'pg-advanced-l4-055', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Row-Level Security', question: 'How do you implement time-based data access policies with RLS?', options: ['Use cron jobs to change permissions', 'Time-based access requires application logic', 'Create RLS policies with temporal conditions using now(), CURRENT_TIMESTAMP, or session variables — enabling data access windows, embargo periods, or time-limited data sharing that is enforced at the database level', 'Time-based policies cause performance issues'], correctAnswer: 2, explanation: 'Time-based RLS policies restrict data access based on temporal conditions. Use cases: 1) Data embargo (cannot see data until release date). 2) Retention policy (cannot see data older than X years). 3) Business hours access (certain data only during work hours). 4) Time-limited sharing (access expires after a date). Since now() is STABLE (consistent within a transaction), it works well in policies. Combine with RESTRICTIVE policies for mandatory temporal constraints.', codeSnippet: "-- Data embargo policy:\nCREATE POLICY embargo ON financial_reports\n  FOR SELECT\n  USING (release_date <= CURRENT_DATE);\n-- Cannot see reports before release date\n\n-- Retention window (last 7 years):\nCREATE POLICY retention ON audit_logs\n  AS RESTRICTIVE\n  FOR SELECT\n  USING (created_at >= now() - interval '7 years');\n\n-- Business hours only:\nCREATE POLICY business_hours ON sensitive_data\n  AS RESTRICTIVE\n  FOR ALL\n  USING (\n    extract(dow from now()) BETWEEN 1 AND 5  -- weekdays\n    AND extract(hour from now()) BETWEEN 9 AND 17\n    OR current_user = 'admin'\n  );\n\n-- Time-limited sharing:\nCREATE TABLE shared_access (\n  document_id INT,\n  shared_with TEXT,\n  expires_at TIMESTAMPTZ\n);\n\nCREATE POLICY time_limited ON documents\n  FOR SELECT\n  USING (\n    owner = current_user\n    OR EXISTS (\n      SELECT 1 FROM shared_access\n      WHERE document_id = documents.id\n        AND shared_with = current_user\n        AND expires_at > now()\n    )\n  );", tags: ['advanced', 'row-level-security', 'time-based', 'temporal'] },
  { id: 'pg-advanced-l4-056', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'JIT Compilation', question: 'How do you compile PostgreSQL with JIT support?', options: ['JIT is always available in all PostgreSQL builds', 'Install the pg_jit extension', 'PostgreSQL must be compiled with --with-llvm flag and the LLVM development libraries must be installed — if built without LLVM, the jit parameter exists but has no effect, and JIT-related EXPLAIN output will not appear', 'JIT requires a special PostgreSQL fork'], correctAnswer: 3, explanation: 'JIT availability depends on build configuration. PostgreSQL must be compiled with --with-llvm and linked against LLVM libraries (version 10+). Most Linux distribution packages include JIT support. Check with pg_config --configure or pg_jit_available(). If LLVM is not available, SET jit = on has no effect. On cloud providers, JIT is typically enabled. For custom builds: install llvm-dev, clang, and use ./configure --with-llvm.', codeSnippet: "-- Check if JIT is available:\nSELECT pg_jit_available();\n-- true = LLVM compiled in\n-- false = no JIT support\n\n-- Check build configuration:\n-- pg_config --configure\n-- Look for: --with-llvm\n\n-- Check LLVM version:\nSHOW jit_provider;  -- 'llvmjit' if available\n\n-- On Ubuntu/Debian:\n-- apt install postgresql-16 postgresql-16-jit\n\n-- Build from source:\n-- sudo apt install llvm-dev clang\n-- ./configure --with-llvm\n-- make && make install\n\n-- Verify in PostgreSQL:\nSELECT name, setting\nFROM pg_settings\nWHERE name IN ('jit', 'jit_provider');\n-- jit          | on\n-- jit_provider | llvmjit\n\n-- If JIT not available:\nSET jit = on;\n-- No error, but no effect\nEXPLAIN ANALYZE SELECT ...;\n-- No JIT section in output", tags: ['advanced', 'jit-compilation', 'llvm', 'build-configuration'] },
  { id: 'pg-advanced-l4-057', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Generated Columns', question: 'How do you use generated columns with geometric and spatial calculations?', options: ['Generated columns cannot store geometry types', 'Use PostGIS functions in triggers only', 'Create generated columns that compute spatial derived values like centroids, areas, lengths, or bounding boxes — these pre-computed values can be indexed for fast filtering without recalculating spatial properties on every query', 'Spatial calculations must be done in application code'], correctAnswer: 0, explanation: 'Generated columns with spatial expressions pre-compute frequently needed geometric properties. Since many PostGIS functions are IMMUTABLE (ST_Area, ST_Length, ST_Centroid for geometry type), they can be used in generated column expressions. This avoids recomputing expensive spatial operations on every query. Common use cases: storing pre-computed area for filtering by size, storing centroid for label placement queries, storing bounding box diagonal for rough size estimates.', codeSnippet: "-- Pre-computed spatial properties:\nCREATE TABLE parcels (\n  id SERIAL PRIMARY KEY,\n  boundary GEOMETRY(Polygon, 32632) NOT NULL,\n  -- Generated spatial columns:\n  area_sqm NUMERIC GENERATED ALWAYS AS (\n    ST_Area(boundary)\n  ) STORED,\n  perimeter_m NUMERIC GENERATED ALWAYS AS (\n    ST_Perimeter(boundary)\n  ) STORED,\n  centroid GEOMETRY(Point, 32632) GENERATED ALWAYS AS (\n    ST_Centroid(boundary)\n  ) STORED,\n  bbox_width NUMERIC GENERATED ALWAYS AS (\n    ST_XMax(boundary) - ST_XMin(boundary)\n  ) STORED\n);\n\n-- Index pre-computed values:\nCREATE INDEX ON parcels (area_sqm);\nCREATE INDEX ON parcels USING gist (centroid);\n\n-- Fast queries on pre-computed values:\nSELECT * FROM parcels\nWHERE area_sqm BETWEEN 500 AND 1000\nORDER BY area_sqm;\n-- Uses B-tree index, no spatial computation!", tags: ['advanced', 'generated-columns', 'spatial', 'postgis'] },
  { id: 'pg-advanced-l4-058', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Parallel Query', question: 'How does parallel hash join work in PostgreSQL?', options: ['Hash joins are always single-threaded', 'Parallel hash join duplicates the hash table per worker', 'In parallel hash join, workers cooperatively build a shared hash table in memory — each worker hashes a portion of the inner relation, then all workers probe the shared table with their portion of the outer relation, avoiding redundant hash table copies', 'Hash joins cannot be parallelized'], correctAnswer: 1, explanation: 'Parallel hash join (added in PG 11) is a key parallel query optimization. Instead of each worker building its own copy of the hash table (which wastes memory), workers cooperatively build a single shared hash table using shared memory. Phase 1: all workers hash-partition the inner relation into the shared table. Phase 2: all workers probe the shared table with their portion of the outer relation. This reduces memory usage by N (number of workers) compared to duplicating.', codeSnippet: "-- Parallel hash join in action:\nSET max_parallel_workers_per_gather = 4;\n\nEXPLAIN (ANALYZE)\nSELECT o.*, c.name\nFROM orders o\nJOIN customers c ON o.customer_id = c.id;\n\n-- Output:\n-- Gather\n--   Workers Planned: 4\n--   Workers Launched: 4\n--   -> Parallel Hash Join\n--       Hash Cond: (o.customer_id = c.id)\n--       -> Parallel Seq Scan on orders o\n--       -> Parallel Hash\n--           -> Seq Scan on customers c\n--           Batches: 1  Memory: 32MB\n\n-- Shared hash table uses:\nSHOW work_mem;  -- shared across workers\nSHOW hash_mem_multiplier;  -- allows larger hash tables\n\n-- Increase for large joins:\nSET work_mem = '256MB';\nSET hash_mem_multiplier = 2.0;\n-- Hash table can use up to 512MB", tags: ['advanced', 'parallel-query', 'hash-join', 'shared-memory'] },
  { id: 'pg-advanced-l4-059', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Custom Operators', question: 'How do you create exclusion constraints using custom operators?', options: ['Exclusion constraints only work with built-in operators', 'Use CHECK constraints for exclusion logic', 'Use EXCLUDE USING index_method (column WITH operator, ...) to create constraints that prevent overlapping or conflicting rows — any GiST or SP-GiST indexable operator that defines an equality or overlap concept can be used in exclusion constraints', 'Exclusion constraints require table-level locks'], correctAnswer: 2, explanation: 'Exclusion constraints generalize UNIQUE constraints. While UNIQUE prevents duplicate values, EXCLUDE prevents rows where specified operator comparisons are all true. Common uses: preventing overlapping time ranges (tsrange WITH &&), preventing overlapping spatial regions (geometry WITH &&), and combined constraints (room WITH =, timerange WITH &&). The constraint requires an index (GiST or SP-GiST) that supports the operators used. Custom operators can be used if they have operator class support.', codeSnippet: "-- Prevent overlapping room bookings:\nCREATE EXTENSION btree_gist;\n\nCREATE TABLE bookings (\n  id SERIAL PRIMARY KEY,\n  room_id INT NOT NULL,\n  during TSTZRANGE NOT NULL,\n  EXCLUDE USING gist (\n    room_id WITH =,     -- same room\n    during WITH &&       -- overlapping time\n  )\n);\n\n-- This succeeds:\nINSERT INTO bookings (room_id, during)\nVALUES (1, '[2024-01-15 09:00, 2024-01-15 10:00)');\n\n-- This fails (overlapping):\nINSERT INTO bookings (room_id, during)\nVALUES (1, '[2024-01-15 09:30, 2024-01-15 11:00)');\n-- ERROR: conflicting key value violates\n--   exclusion constraint\n\n-- Different room is OK:\nINSERT INTO bookings (room_id, during)\nVALUES (2, '[2024-01-15 09:30, 2024-01-15 11:00)');\n-- Success: different room_id\n\n-- Spatial exclusion (no overlapping territories):\nCREATE TABLE territories (\n  id SERIAL,\n  region GEOMETRY(Polygon, 4326),\n  EXCLUDE USING gist (region WITH &&)\n);", tags: ['advanced', 'custom-operators', 'exclusion-constraint', 'gist'] },
  { id: 'pg-advanced-l4-060', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'How do you implement event sourcing with logical decoding?', options: ['Event sourcing requires a specialized event store', 'Use a regular table as an event store only', 'Combine an append-only event table with logical decoding to stream events — the event table captures all state changes as immutable events, and logical decoding propagates these events to downstream consumers for building projections, read models, and external system synchronization', 'Event sourcing is incompatible with PostgreSQL'], correctAnswer: 3, explanation: 'Event sourcing with PostgreSQL: 1) Store events in an append-only table (no updates or deletes). 2) Use logical decoding to stream events to consumers (projections, read models, external systems). 3) The WAL acts as the durable event log. 4) Consumers build materialized state from the event stream. 5) pg_logical_emit_message can add metadata events. This architecture provides full audit trail, temporal queries, and decoupled read/write models.', codeSnippet: "-- Event store table:\nCREATE TABLE events (\n  id BIGSERIAL PRIMARY KEY,\n  aggregate_id UUID NOT NULL,\n  aggregate_type TEXT NOT NULL,\n  event_type TEXT NOT NULL,\n  event_data JSONB NOT NULL,\n  metadata JSONB DEFAULT '{}',\n  created_at TIMESTAMPTZ DEFAULT now(),\n  version INT NOT NULL\n);\n\n-- Ensure event ordering per aggregate:\nCREATE UNIQUE INDEX ON events (aggregate_id, version);\n\n-- Publication for event streaming:\nCREATE PUBLICATION event_stream\n  FOR TABLE events\n  WITH (publish = 'insert');  -- only inserts\n\n-- Consumers subscribe to the event stream:\n-- Consumer 1: builds read model\n-- Consumer 2: sends emails\n-- Consumer 3: updates search index\n\n-- Append event:\nINSERT INTO events (\n  aggregate_id, aggregate_type, event_type,\n  event_data, version\n) VALUES (\n  'order-123', 'Order', 'OrderPlaced',\n  '{\"items\": [...], \"total\": 99.99}',\n  1\n);", tags: ['advanced', 'logical-decoding', 'event-sourcing', 'cqrs'] },
  { id: 'pg-advanced-l4-061', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Row-Level Security', question: 'How do you audit RLS policy decisions for compliance?', options: ['RLS decisions are not auditable', 'Check PostgreSQL logs for RLS information', 'Enable log_statement and log_replication_commands, use pgaudit extension for detailed audit logging, and create wrapper functions that log policy evaluations — this provides a compliance audit trail showing who accessed what data and which policies applied', 'RLS audit requires a commercial product'], correctAnswer: 0, explanation: 'RLS audit approaches: 1) pgaudit extension logs all SQL statements with user context. 2) Custom audit triggers on tables record actual data access. 3) EXPLAIN output shows which policies are applied. 4) Wrapper views/functions that log access before returning data. 5) pg_stat_user_tables tracks access patterns. 6) For SOX/HIPAA compliance, combine pgaudit with log aggregation. The challenge is that RLS is transparent — users do not know they cannot see filtered rows, making traditional logging insufficient.', codeSnippet: "-- Install pgaudit for comprehensive logging:\nCREATE EXTENSION pgaudit;\n\n-- Configure audit logging:\nALTER SYSTEM SET pgaudit.log = 'read, write, ddl';\nALTER SYSTEM SET pgaudit.log_catalog = off;\nALTER SYSTEM SET pgaudit.log_relation = on;\n\n-- Per-table audit:\nSELECT audit.set_table_audit('documents', TRUE);\n\n-- Custom access logging function:\nCREATE FUNCTION log_data_access(table_name TEXT, row_count INT)\nRETURNS VOID AS $$\nBEGIN\n  INSERT INTO access_audit_log(\n    user_name, table_accessed, rows_returned,\n    access_time, client_ip\n  ) VALUES (\n    current_user, table_name, row_count,\n    now(), inet_client_addr()\n  );\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- Verify policy application:\nSET ROLE restricted_user;\nEXPLAIN (VERBOSE)\nSELECT * FROM sensitive_table;\n-- Shows: Filter: (tenant_id = ...)\n-- Confirms RLS policy is active", tags: ['advanced', 'row-level-security', 'auditing', 'compliance'] },
  { id: 'pg-advanced-l4-062', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Generated Columns', question: 'How do you use generated columns for natural language processing preprocessing?', options: ['NLP requires external processing only', 'Generated columns cannot process text', 'Create generated columns that preprocess text for NLP tasks — such as generating tsvectors for search, extracting word counts, computing text hashes for deduplication, or creating normalized versions for comparison, all automatically synchronized with source text', 'Use triggers for all text preprocessing'], correctAnswer: 1, explanation: 'Generated columns can automate NLP preprocessing at the database level: 1) tsvector generation for full-text search. 2) Word count for content metrics. 3) Text fingerprints (MD5/SHA) for deduplication. 4) Lowercase/trimmed/normalized versions for comparison. 5) Language detection hints from character analysis. These computed values update automatically when the source text changes, eliminating the need for application-level preprocessing pipelines.', codeSnippet: "-- NLP preprocessing with generated columns:\nCREATE TABLE articles (\n  id SERIAL PRIMARY KEY,\n  title TEXT NOT NULL,\n  body TEXT NOT NULL,\n  -- Full-text search vector:\n  search_vec TSVECTOR GENERATED ALWAYS AS (\n    setweight(to_tsvector('english', title), 'A') ||\n    setweight(to_tsvector('english', body), 'B')\n  ) STORED,\n  -- Word count:\n  word_count INT GENERATED ALWAYS AS (\n    array_length(string_to_array(body, ' '), 1)\n  ) STORED,\n  -- Content fingerprint for dedup:\n  content_hash TEXT GENERATED ALWAYS AS (\n    md5(lower(regexp_replace(body, '\\s+', ' ', 'g')))\n  ) STORED,\n  -- Title slug:\n  slug TEXT GENERATED ALWAYS AS (\n    lower(regexp_replace(\n      regexp_replace(title, '[^a-zA-Z0-9\\s]', '', 'g'),\n      '\\s+', '-', 'g'\n    ))\n  ) STORED\n);\n\nCREATE INDEX ON articles USING gin (search_vec);\nCREATE INDEX ON articles (word_count);\nCREATE UNIQUE INDEX ON articles (content_hash);", tags: ['advanced', 'generated-columns', 'nlp', 'text-preprocessing'] },
  { id: 'pg-advanced-l4-063', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Parallel Query', question: 'How do you diagnose parallel query issues and why parallel plans are not chosen?', options: ['Parallel plans are always chosen when beneficial', 'Use EXPLAIN ANALYZE only', 'Set force_parallel_mode = on to force parallel execution and compare plans — check for PARALLEL UNSAFE functions, temporary table access, serializable isolation, cursor queries, and verify that max_parallel_workers_per_gather and related cost parameters are properly configured', 'Parallel query issues cannot be diagnosed'], correctAnswer: 2, explanation: 'Diagnosing parallel query non-use: 1) force_parallel_mode = on forces parallel plan attempts. 2) EXPLAIN shows why parallel was not chosen. 3) Check function parallel safety (pg_proc.proparallel). 4) Verify worker availability (max_worker_processes, max_parallel_workers). 5) Check cost parameters (parallel_setup_cost, parallel_tuple_cost). 6) Verify table is large enough (min_parallel_table_scan_size). 7) Check for blockers (temp tables, serializable, cursors). 8) Workers may all be busy (check pg_stat_activity).', codeSnippet: "-- Force parallel to see if it is possible:\nSET force_parallel_mode = on;\nEXPLAIN (ANALYZE, VERBOSE)\nSELECT COUNT(*) FROM my_table WHERE condition;\n\n-- If no parallel plan, check:\n-- 1. Function safety:\nSELECT proname, proparallel\nFROM pg_proc\nWHERE proname IN ('my_function');\n-- 'u' = unsafe, blocks parallelism\n\n-- 2. Worker availability:\nSELECT count(*) FROM pg_stat_activity\nWHERE backend_type = 'parallel worker';\nSHOW max_parallel_workers;  -- total limit\n\n-- 3. Table too small:\nSELECT pg_size_pretty(pg_relation_size('my_table'));\nSHOW min_parallel_table_scan_size;  -- default 8MB\n\n-- 4. Cost parameters:\nSHOW parallel_setup_cost;   -- 1000\nSHOW parallel_tuple_cost;   -- 0.1\n-- Lower these for more parallelism\n\n-- 5. Check for blockers:\nSHOW transaction_isolation;  -- serializable blocks\n-- Temp table access blocks parallelism", tags: ['advanced', 'parallel-query', 'diagnostics', 'troubleshooting'] },
  { id: 'pg-advanced-l4-064', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Spatial Indexing', question: 'How do you implement spatial full-text search combining PostGIS with tsvector?', options: ['Spatial and text search cannot be combined', 'Use separate queries and merge results', 'Create a composite GiST index using both geometry and tsvector columns (via btree_gist for the tsvector), or use separate GIN and GiST indexes that PostgreSQL combines with BitmapAnd — enabling queries that filter by both location and text content efficiently', 'Full-text search does not work with spatial data'], correctAnswer: 3, explanation: 'Combining spatial and text search: 1) Separate indexes (GiST for geometry, GIN for tsvector) with BitmapAnd. 2) Composite GiST index (requires btree_gist). 3) Multi-column GIN with btree_gin for simple spatial filters. The query planner automatically combines multiple indexes via bitmap scans. For "find restaurants near me matching keyword", this approach provides sub-millisecond results on millions of rows.', codeSnippet: "-- Separate indexes combined by planner:\nCREATE INDEX idx_spatial ON places USING gist (location);\nCREATE INDEX idx_fts ON places USING gin (search_vector);\n\n-- Combined query:\nSELECT name, address,\n  ST_Distance(location::geography, my_point::geography) AS dist\nFROM places\nWHERE search_vector @@ plainto_tsquery('sushi restaurant')\n  AND ST_DWithin(location::geography, my_point::geography, 2000)\nORDER BY location <-> my_point\nLIMIT 10;\n\n-- Plan shows BitmapAnd:\n-- BitmapAnd\n--   -> Bitmap Index Scan on idx_fts\n--   -> Bitmap Index Scan on idx_spatial\n\n-- Alternative: composite GiST\nCREATE EXTENSION btree_gist;\nCREATE INDEX idx_combined\n  ON places USING gist (location, search_vector);\n\n-- For text + location + category:\nCREATE INDEX idx_multi\n  ON places USING gist (\n    location,\n    category  -- via btree_gist\n  );", tags: ['advanced', 'spatial-indexing', 'full-text-search', 'combined-index'] },
  { id: 'pg-advanced-l4-065', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Custom Operators', question: 'How do you create hash operators and support functions for custom types?', options: ['Hash support is only for built-in types', 'Use MD5 for custom hash support', 'Implement a hash function for your custom type and create a hash operator class — this enables hash joins, hash aggregation, and hash indexes for the custom type, which is essential for equality-based operations on large datasets', 'Hash indexes are deprecated'], correctAnswer: 0, explanation: 'Hash support requires: 1) A hash function that returns INT4 for the custom type. 2) A hash operator class for the hash access method. The hash function must be consistent with equality (equal values must produce equal hashes). Hash support enables: hash joins (faster than merge join for certain sizes), hash aggregation (GROUP BY), hash partitioning, and hash indexes. Without hash support, PostgreSQL falls back to sort-based operations which can be slower.', codeSnippet: "-- Hash function for custom type:\nCREATE FUNCTION my_type_hash(my_type)\nRETURNS INT4 AS $$\n  SELECT hashtext($1::TEXT);\n$$ LANGUAGE sql IMMUTABLE STRICT;\n\n-- Extended hash function (for hash partitioning):\nCREATE FUNCTION my_type_hash_extended(my_type, BIGINT)\nRETURNS BIGINT AS $$\n  SELECT hashtextextended($1::TEXT, $2);\n$$ LANGUAGE sql IMMUTABLE STRICT;\n\n-- Hash operator class:\nCREATE OPERATOR CLASS my_type_hash_ops\n  DEFAULT FOR TYPE my_type\n  USING hash AS\n  OPERATOR 1 = (my_type, my_type),\n  FUNCTION 1 my_type_hash(my_type),\n  FUNCTION 2 my_type_hash_extended(my_type, BIGINT);\n\n-- Now hash joins work:\nSELECT * FROM table_a a\nJOIN table_b b ON a.my_col = b.my_col;\n-- Can use Hash Join!\n\n-- Hash index works:\nCREATE INDEX ON my_table USING hash (my_col);\n\n-- Hash partitioning works:\nCREATE TABLE partitioned (...)\n  PARTITION BY HASH (my_col);", tags: ['advanced', 'custom-operators', 'hash-support', 'operator-class'] },
  { id: 'pg-advanced-l4-066', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Row-Level Security', question: 'How do you implement hierarchical access control with RLS?', options: ['RLS only supports flat permission models', 'Use nested views for hierarchy', 'Create RLS policies that traverse an organizational hierarchy — using recursive CTEs or ltree paths in the policy expression to grant access based on reporting chains, department trees, or organizational unit membership', 'Hierarchical access requires LDAP integration'], correctAnswer: 1, explanation: 'Hierarchical RLS implements access rules based on organizational structure. A manager sees their own data plus all subordinates (direct and indirect). Approaches: 1) Recursive CTE in the policy (can be expensive). 2) Materialized path (ltree type) for fast ancestry checks. 3) Pre-computed closure table for fast lookups. 4) Array of ancestor IDs for containment checks. The ltree approach is most efficient as it supports GiST indexes for path operations.', codeSnippet: "CREATE EXTENSION ltree;\n\n-- Org hierarchy with ltree:\nCREATE TABLE org_units (\n  id INT PRIMARY KEY,\n  path LTREE NOT NULL,  -- 'corp.eng.backend'\n  name TEXT\n);\nCREATE INDEX ON org_units USING gist (path);\n\n-- Users with org unit:\nCREATE TABLE users (\n  id INT PRIMARY KEY,\n  name TEXT,\n  org_path LTREE NOT NULL\n);\n\n-- Data with org unit:\nCREATE TABLE projects (\n  id INT PRIMARY KEY,\n  name TEXT,\n  org_path LTREE NOT NULL,\n  data TEXT\n);\n\nALTER TABLE projects ENABLE ROW LEVEL SECURITY;\n\n-- Hierarchical policy: see your level and below\nCREATE POLICY org_hierarchy ON projects\n  USING (\n    org_path <@ (\n      SELECT u.org_path FROM users u\n      WHERE u.id = current_setting('app.user_id')::INT\n    )\n  );\n\n-- User at 'corp.eng' sees:\n-- corp.eng, corp.eng.backend, corp.eng.frontend\n-- But NOT: corp.sales, corp.hr", tags: ['advanced', 'row-level-security', 'hierarchical', 'ltree'] },
  { id: 'pg-advanced-l4-067', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'How do you handle schema evolution with logical replication?', options: ['Schema changes are automatically replicated', 'Schema evolution breaks logical replication', 'DDL changes are not replicated — schema changes must be applied manually on both publisher and subscriber, with careful ordering to avoid replication failures, using techniques like adding columns with defaults, pre-creating columns on subscriber, and coordinated deployment', 'Use physical replication for schema changes'], correctAnswer: 2, explanation: 'Logical replication does not replicate DDL. Schema evolution requires coordination: 1) Adding a nullable column: add on subscriber first, then publisher. 2) Adding NOT NULL with default: add on subscriber first (with default), then publisher. 3) Removing a column: remove from publication first, then drop on publisher, then subscriber. 4) Changing column type: requires careful migration. 5) Use pg_logical_emit_message to signal schema changes. Column matching is by name, not position.', codeSnippet: "-- Safe column addition:\n-- Step 1: Add on subscriber (with default)\nALTER TABLE orders ADD COLUMN priority TEXT DEFAULT 'normal';\n\n-- Step 2: Add on publisher\nALTER TABLE orders ADD COLUMN priority TEXT DEFAULT 'normal';\n-- Replication continues seamlessly\n\n-- Safe column removal:\n-- Step 1: Remove from publication\nALTER PUBLICATION my_pub\n  SET TABLE orders (id, customer, total);\n-- Excludes 'old_column'\n\n-- Step 2: Drop on publisher\nALTER TABLE orders DROP COLUMN old_column;\n\n-- Step 3: Drop on subscriber\nALTER TABLE orders DROP COLUMN old_column;\n\n-- Type change (risky!):\n-- Must pause replication, change both sides, resume\nALTER SUBSCRIPTION my_sub DISABLE;\n-- Change type on both sides\nALTER TABLE orders ALTER COLUMN amount TYPE NUMERIC(12,2);\nALTER SUBSCRIPTION my_sub ENABLE;\n\n-- Monitor for replication errors:\nSELECT * FROM pg_stat_subscription;", tags: ['advanced', 'logical-decoding', 'schema-evolution', 'ddl'] },
  { id: 'pg-advanced-l4-068', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Background Workers', question: 'How do you use pg_partman for automatic partition management?', options: ['pg_partman is a CLI tool run externally', 'pg_partman modifies postgresql.conf', 'pg_partman is an extension with a background worker that automatically creates, detaches, and drops partitions based on time or serial ranges — it manages the partition lifecycle so you do not need manual partition creation scripts', 'pg_partman only works with inheritance-based partitioning'], correctAnswer: 3, explanation: 'pg_partman automates partition management for both declarative and inheritance-based partitioning. It handles: 1) Pre-creating future partitions (premake). 2) Detaching/dropping old partitions (retention). 3) Partition naming and creation. 4) Default partition management. The background worker (BGW) runs periodically to maintain partitions. Configuration is stored in the part.part_config table. It supports time-based (daily, monthly, yearly) and serial-based partitioning.', codeSnippet: "-- Install pg_partman:\nCREATE EXTENSION pg_partman;\n\n-- Create parent partitioned table:\nCREATE TABLE events (\n  id BIGSERIAL,\n  created_at TIMESTAMPTZ NOT NULL,\n  data JSONB\n) PARTITION BY RANGE (created_at);\n\n-- Configure automatic management:\nSELECT partman.create_parent(\n  p_parent_table := 'public.events',\n  p_control := 'created_at',\n  p_type := 'native',\n  p_interval := 'monthly',\n  p_premake := 3  -- create 3 months ahead\n);\n\n-- Set retention (drop partitions older than 2 years):\nUPDATE partman.part_config\nSET retention = '2 years',\n    retention_keep_table = FALSE\nWHERE parent_table = 'public.events';\n\n-- Manual maintenance run:\nSELECT partman.run_maintenance();\n\n-- Or let the BGW handle it:\n-- postgresql.conf:\n-- shared_preload_libraries = 'pg_partman_bgw'\n-- pg_partman_bgw.interval = 3600  -- check hourly", tags: ['advanced', 'background-workers', 'pg-partman', 'partition-management'] },
  { id: 'pg-advanced-l4-069', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'JIT Compilation', question: 'How do you use JIT with custom C functions?', options: ['Custom C functions cannot benefit from JIT', 'JIT automatically compiles C functions', 'Custom C functions benefit from JIT when they are inlined — provide LLVM bitcode alongside the shared library by compiling with clang -emit-llvm, allowing the JIT compiler to inline the function body into the expression evaluation code', 'JIT and C extensions are incompatible'], correctAnswer: 0, explanation: 'For JIT to inline custom C functions, LLVM bitcode of the function must be available. Extensions can provide bitcode by compiling with clang -emit-llvm and installing the .bc files alongside the .so files. When JIT encounters a call to such a function, it can inline the function body, eliminating function call overhead and enabling cross-function optimization. Without bitcode, JIT still compiles the surrounding expressions but treats the function as an opaque call.', codeSnippet: "-- Build extension with LLVM bitcode:\n-- Makefile:\n-- MODULES = my_extension\n-- OBJS = my_funcs.o\n-- USE_PGXS = 1\n-- with_llvm = yes  # enable bitcode generation\n-- include $(PGXS)\n\n-- Compile:\n-- make USE_PGXS=1 with_llvm=yes\n-- make install\n\n-- The build produces:\n-- my_funcs.so  (shared library)\n-- my_funcs.bc  (LLVM bitcode for JIT inlining)\n\n-- Verify bitcode is installed:\n-- ls $(pg_config --pkglibdir)/bitcode/my_extension/\n-- my_funcs.index.bc\n-- my_funcs/my_funcs.bc\n\n-- JIT inlines the function:\nEXPLAIN (ANALYZE) SELECT my_func(col) FROM large_table;\n-- JIT:\n--   Inlining: true  -- my_func was inlined!\n--   Functions: 5", tags: ['advanced', 'jit-compilation', 'c-extensions', 'bitcode'] },
  { id: 'pg-advanced-l4-070', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Generated Columns', question: 'How do you handle generated column dependencies during ALTER TABLE?', options: ['Generated columns have no ALTER TABLE restrictions', 'Drop and recreate the table for any change', 'You cannot directly change a column that a generated column depends on — you must drop the generated column first, alter the source column, then recreate the generated column, because the generated expression is checked for validity against current column types', 'Generated columns auto-update their expressions'], correctAnswer: 1, explanation: 'Generated column dependencies create restrictions on ALTER TABLE: 1) Cannot drop a column referenced by a generated column. 2) Cannot change the type of a referenced column. 3) Must drop generated column first, make changes, then recreate. 4) Cannot add generated column that references another generated column. This is because the generated expression is compiled and validated at definition time. Plan schema changes carefully when generated columns are involved.', codeSnippet: "-- Table with generated column:\nCREATE TABLE items (\n  price NUMERIC,\n  quantity INT,\n  total NUMERIC GENERATED ALWAYS AS (price * quantity) STORED\n);\n\n-- Cannot change type of referenced column:\nALTER TABLE items ALTER COLUMN price TYPE FLOAT;\n-- ERROR: cannot alter type of column used by generated column\n\n-- Must drop generated, alter, recreate:\nALTER TABLE items DROP COLUMN total;\nALTER TABLE items ALTER COLUMN price TYPE FLOAT;\nALTER TABLE items ADD COLUMN total FLOAT\n  GENERATED ALWAYS AS (price * quantity) STORED;\n\n-- Cannot drop referenced column:\nALTER TABLE items DROP COLUMN price;\n-- ERROR: cannot drop column used by generated column\n\n-- Must use CASCADE:\nALTER TABLE items DROP COLUMN price CASCADE;\n-- Drops price AND total\n\n-- Script for safe schema changes:\nBEGIN;\n  ALTER TABLE items DROP COLUMN total;\n  ALTER TABLE items ALTER COLUMN price TYPE NUMERIC(10,2);\n  ALTER TABLE items ADD COLUMN total NUMERIC(12,2)\n    GENERATED ALWAYS AS (price * quantity) STORED;\nCOMMIT;", tags: ['advanced', 'generated-columns', 'alter-table', 'dependencies'] },
  { id: 'pg-advanced-l4-071', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Parallel Query', question: 'How do you use parallel query with aggregate pushdown and partial aggregation?', options: ['Aggregation is always done by the leader', 'Only SUM and COUNT support parallelism', 'PostgreSQL uses partial aggregation where each parallel worker computes a partial aggregate, then the leader combines them — this works for SUM, COUNT, AVG, MIN, MAX, and any custom aggregate with a combinefunc, dramatically speeding up analytical queries', 'Parallel aggregation requires special syntax'], correctAnswer: 2, explanation: 'Parallel aggregation uses a two-phase approach: 1) Partial Aggregate: each worker processes its portion of data using the regular sfunc, producing a partial state. 2) Finalize Aggregate: the leader combines partial states using combinefunc (for custom aggregates) or built-in combination logic. For AVG, workers compute partial sum and count, then the leader computes sum/count. For MIN/MAX, workers find local extremes, leader finds global. EXPLAIN shows Partial Aggregate and Finalize Aggregate nodes.', codeSnippet: "-- Parallel aggregation:\nSET max_parallel_workers_per_gather = 4;\n\nEXPLAIN (ANALYZE)\nSELECT\n  department,\n  COUNT(*) AS emp_count,\n  AVG(salary) AS avg_salary,\n  MAX(salary) AS max_salary\nFROM employees\nGROUP BY department;\n\n-- Plan:\n-- Finalize GroupAggregate\n--   Group Key: department\n--   -> Gather Merge\n--     Workers: 4\n--     -> Sort\n--       -> Partial GroupAggregate\n--           Group Key: department\n--           -> Parallel Seq Scan on employees\n\n-- Each worker: Partial GroupAggregate\n--   (partial count, partial sum for avg, partial max)\n-- Leader: Finalize GroupAggregate\n--   (combine partials into final results)\n\n-- Parallel hash aggregate (no sort needed):\nSET enable_hashagg = on;\nEXPLAIN (ANALYZE)\nSELECT status, COUNT(*) FROM large_table\nGROUP BY status;\n-- Finalize HashAggregate\n--   -> Partial HashAggregate (per worker)", tags: ['advanced', 'parallel-query', 'aggregation', 'partial-aggregate'] },
  { id: 'pg-advanced-l4-072', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Spatial Indexing', question: 'How do you implement R-tree-like spatial indexing behavior in PostgreSQL?', options: ['PostgreSQL has a built-in R-tree index', 'R-tree behavior is only in commercial databases', 'PostgreSQL GiST index for PostGIS geometries implements R-tree-like behavior — it organizes spatial data into hierarchical bounding boxes, enabling efficient spatial searches through tree traversal, with automatic balancing and support for concurrent access', 'Use a custom extension for R-tree'], correctAnswer: 3, explanation: 'PostgreSQL removed its original R-tree index type in PG 8.2, replacing it with GiST which provides R-tree behavior more flexibly. The PostGIS GiST index builds a balanced tree of bounding boxes. Internal nodes contain bounding boxes that enclose all child bounding boxes. Leaf nodes contain bounding boxes of actual geometries. Searches traverse from root, pruning branches whose bounding boxes do not intersect the query area. This provides O(log n) search performance for spatial queries.', codeSnippet: "-- GiST provides R-tree behavior:\nCREATE INDEX idx_rtree_like\n  ON buildings USING gist (footprint);\n\n-- The index tree structure:\n-- Root: bbox of entire dataset\n--   Internal: bbox of subset\n--     Leaf: bbox of individual geometry\n\n-- Inspect index structure:\nCREATE EXTENSION pageinspect;\n\n-- Check index page:\nSELECT * FROM gist_page_items(\n  get_raw_page('idx_rtree_like', 0), 'idx_rtree_like'\n);\n\n-- Index statistics:\nSELECT\n  pg_size_pretty(pg_relation_size('idx_rtree_like')) AS size,\n  pg_stat_get_numscans('idx_rtree_like'::regclass) AS scans\nFROM pg_class WHERE relname = 'idx_rtree_like';\n\n-- GiST tuning parameters:\nCREATE INDEX idx_tuned ON buildings\n  USING gist (footprint)\n  WITH (buffering = on,  -- buffered build (faster)\n        fillfactor = 90); -- leave room for updates", tags: ['advanced', 'spatial-indexing', 'rtree', 'gist-internals'] },
  { id: 'pg-advanced-l4-073', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Custom Operators', question: 'How do you register custom operators for use with partial indexes and index-only scans?', options: ['Partial indexes do not support custom operators', 'Use WHERE clause functions instead', 'Custom operators with proper operator classes support partial indexes (CREATE INDEX ... WHERE custom_op) and index-only scans (when the operator is part of an operator family) — the operator must be indexable through its operator class definition', 'Index-only scans only work with built-in operators'], correctAnswer: 0, explanation: 'For custom operators to work with partial indexes and index-only scans: 1) The operator must have an operator class. 2) The operator class must be registered for the appropriate index access method. 3) For index-only scans, the operator must be part of an operator family that the index access method supports. 4) Partial indexes can use any operator in their WHERE clause that is IMMUTABLE. 5) The planner checks operator families to determine if an index-only scan is possible.', codeSnippet: "-- Custom operator with index support:\nCREATE FUNCTION priority_gt(a TEXT, b TEXT)\nRETURNS BOOLEAN AS $$\n  SELECT CASE a\n    WHEN 'critical' THEN 4\n    WHEN 'high' THEN 3\n    WHEN 'medium' THEN 2\n    ELSE 1\n  END > CASE b\n    WHEN 'critical' THEN 4\n    WHEN 'high' THEN 3\n    WHEN 'medium' THEN 2\n    ELSE 1\n  END;\n$$ LANGUAGE sql IMMUTABLE;\n\nCREATE OPERATOR >> (\n  FUNCTION = priority_gt,\n  LEFTARG = TEXT,\n  RIGHTARG = TEXT\n);\n\n-- Partial index using custom operator:\nCREATE INDEX idx_critical_tasks\n  ON tasks (assigned_to)\n  WHERE priority >> 'medium';\n\n-- Query uses the partial index:\nSELECT * FROM tasks\nWHERE priority >> 'medium'\n  AND assigned_to = 'alice';\n-- Bitmap Index Scan on idx_critical_tasks", tags: ['advanced', 'custom-operators', 'partial-index', 'index-only-scan'] },
  { id: 'pg-advanced-l4-074', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Row-Level Security', question: 'How do you implement data classification labels with RLS?', options: ['Data classification requires a separate system', 'Use column-level encryption for classification', 'Assign classification labels to rows and create RLS policies that compare user clearance against row classification — implementing mandatory access control (MAC) where the database enforces that users cannot access data above their clearance level', 'Classification labels are application-level only'], correctAnswer: 1, explanation: 'Data classification with RLS implements a form of Mandatory Access Control (MAC): 1) Each row has a classification label (unclassified, confidential, secret, top_secret). 2) Each user has a clearance level. 3) RLS policies enforce that users can only see rows at or below their clearance. 4) Write policies can enforce that users can only create rows at their level. This is used in government, healthcare (HIPAA), and financial (SOX) applications.', codeSnippet: "-- Classification system:\nCREATE TYPE classification AS ENUM (\n  'unclassified', 'confidential', 'secret', 'top_secret'\n);\n\nCREATE TABLE classified_documents (\n  id SERIAL PRIMARY KEY,\n  title TEXT,\n  content TEXT,\n  label classification NOT NULL DEFAULT 'unclassified',\n  owner TEXT DEFAULT current_user\n);\n\nALTER TABLE classified_documents\n  ENABLE ROW LEVEL SECURITY;\n\n-- MAC policy: user clearance >= document label\nCREATE POLICY mac_read ON classified_documents\n  FOR SELECT\n  USING (\n    ARRAY_POSITION(\n      ARRAY['unclassified','confidential','secret','top_secret']::TEXT[],\n      current_setting('app.clearance')\n    ) >= ARRAY_POSITION(\n      ARRAY['unclassified','confidential','secret','top_secret']::TEXT[],\n      label::TEXT\n    )\n  );\n\n-- Set user clearance:\nSET app.clearance = 'secret';\nSELECT * FROM classified_documents;\n-- Sees: unclassified, confidential, secret\n-- NOT: top_secret", tags: ['advanced', 'row-level-security', 'data-classification', 'mac'] },
  { id: 'pg-advanced-l4-075', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'How do you use logical decoding for real-time materialized view refresh?', options: ['Materialized views auto-refresh from WAL', 'Use triggers for real-time materialized views', 'Consume the logical decoding change stream to incrementally update materialized views — instead of full REFRESH, apply only the changed rows to the materialized view, providing near-real-time freshness without the overhead of complete recalculation', 'Real-time materialized views are not possible'], correctAnswer: 2, explanation: 'Incremental materialized view refresh using logical decoding: 1) Create a logical replication slot. 2) Monitor changes to base tables. 3) For each change, compute the delta effect on the materialized view. 4) Apply the delta (insert/update/delete on the materialized view). This is the pattern used by tools like pg_ivm (Incremental View Maintenance). It is much faster than full REFRESH for views where only a small fraction of base data changes between refreshes.', codeSnippet: "-- Concept: incremental MV refresh via CDC\n-- Base table:\nCREATE TABLE orders (\n  id SERIAL PRIMARY KEY,\n  product_id INT,\n  quantity INT,\n  total NUMERIC\n);\n\n-- Materialized aggregate:\nCREATE TABLE mv_product_stats (\n  product_id INT PRIMARY KEY,\n  order_count BIGINT DEFAULT 0,\n  total_quantity BIGINT DEFAULT 0,\n  total_revenue NUMERIC DEFAULT 0\n);\n\n-- CDC-based incremental update function:\nCREATE FUNCTION apply_order_change()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    INSERT INTO mv_product_stats (product_id, order_count,\n      total_quantity, total_revenue)\n    VALUES (NEW.product_id, 1, NEW.quantity, NEW.total)\n    ON CONFLICT (product_id) DO UPDATE\n    SET order_count = mv_product_stats.order_count + 1,\n        total_quantity = mv_product_stats.total_quantity + NEW.quantity,\n        total_revenue = mv_product_stats.total_revenue + NEW.total;\n  ELSIF TG_OP = 'DELETE' THEN\n    UPDATE mv_product_stats\n    SET order_count = order_count - 1,\n        total_quantity = total_quantity - OLD.quantity,\n        total_revenue = total_revenue - OLD.total\n    WHERE product_id = OLD.product_id;\n  END IF;\n  RETURN NULL;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'logical-decoding', 'incremental-refresh', 'materialized-view'] },
  { id: 'pg-advanced-l4-076', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Generated Columns', question: 'How do you use generated columns for multi-column deduplication?', options: ['Deduplication only works with single columns', 'Use application-level deduplication', 'Create a generated column that computes a hash or normalized key from multiple columns — then apply a unique index on the generated column to prevent duplicates based on the combined values, handling case-insensitivity, whitespace, and format normalization', 'Use triggers with custom dedup logic'], correctAnswer: 3, explanation: 'Generated columns for deduplication compute a normalized fingerprint from multiple columns. This handles cases where duplicates differ in case, whitespace, or formatting. The generated column stores a consistent hash or normalized key. A UNIQUE index on this column prevents duplicates. This is more efficient than UNIQUE constraints on multiple columns with expression indexes because the normalization happens once on write, not on every comparison.', codeSnippet: "-- Multi-column deduplication:\nCREATE TABLE contacts (\n  id SERIAL PRIMARY KEY,\n  first_name TEXT,\n  last_name TEXT,\n  email TEXT,\n  phone TEXT,\n  -- Dedup key: normalized composite\n  dedup_key TEXT GENERATED ALWAYS AS (\n    md5(\n      lower(trim(coalesce(first_name, ''))) || '|' ||\n      lower(trim(coalesce(last_name, ''))) || '|' ||\n      lower(trim(coalesce(email, ''))) || '|' ||\n      regexp_replace(coalesce(phone, ''), '[^0-9]', '', 'g')\n    )\n  ) STORED\n);\n\n-- Unique constraint on dedup key:\nCREATE UNIQUE INDEX ON contacts (dedup_key);\n\n-- These are considered duplicates:\nINSERT INTO contacts (first_name, last_name, email, phone)\nVALUES ('John', 'Doe', 'john@example.com', '555-1234');\n-- OK\n\nINSERT INTO contacts (first_name, last_name, email, phone)\nVALUES ('JOHN', ' Doe ', 'JOHN@example.com', '(555) 1234');\n-- ERROR: duplicate key (dedup_key matches)", tags: ['advanced', 'generated-columns', 'deduplication', 'unique-index'] },
  { id: 'pg-advanced-l4-077', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Parallel Query', question: 'How do you configure parallel query for different workload types?', options: ['One parallel configuration fits all workloads', 'Parallel query only benefits data warehouses', 'Configure different parallel settings per role, database, or session — OLTP workloads benefit from fewer or no parallel workers (low latency), while OLAP workloads benefit from maximum parallelism (high throughput), using ALTER ROLE/DATABASE SET for workload isolation', 'Parallel settings cannot be customized per user'], correctAnswer: 0, explanation: 'Workload-specific parallel configuration: 1) OLTP: SET max_parallel_workers_per_gather = 0 (or 1), high jit_above_cost, low work_mem. 2) OLAP: max_parallel_workers_per_gather = 8+, lower parallel costs, high work_mem. 3) Mixed: use role-based settings. 4) ETL: max parallelism during load windows. ALTER ROLE and ALTER DATABASE allow setting these per-workload without affecting others. Connection poolers can route to different roles.', codeSnippet: "-- OLTP role (minimize latency):\nALTER ROLE oltp_user SET max_parallel_workers_per_gather = 0;\nALTER ROLE oltp_user SET jit = off;\nALTER ROLE oltp_user SET work_mem = '4MB';\n\n-- OLAP role (maximize throughput):\nALTER ROLE analyst SET max_parallel_workers_per_gather = 8;\nALTER ROLE analyst SET jit = on;\nALTER ROLE analyst SET jit_above_cost = 50000;\nALTER ROLE analyst SET work_mem = '256MB';\nALTER ROLE analyst SET enable_partitionwise_join = on;\nALTER ROLE analyst SET enable_partitionwise_aggregate = on;\n\n-- ETL role (bulk operations):\nALTER ROLE etl_user SET max_parallel_workers_per_gather = 4;\nALTER ROLE etl_user SET max_parallel_maintenance_workers = 4;\nALTER ROLE etl_user SET maintenance_work_mem = '1GB';\n\n-- Per-database settings:\nALTER DATABASE analytics\n  SET max_parallel_workers_per_gather = 6;\nALTER DATABASE production\n  SET max_parallel_workers_per_gather = 2;", tags: ['advanced', 'parallel-query', 'workload-management', 'configuration'] },
  { id: 'pg-advanced-l4-078', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Custom Operators', question: 'How do you implement a custom GiST operator class for a new data type?', options: ['GiST only supports geometry and range types', 'Implement a B-tree operator class instead', 'Implement the required GiST support functions (consistent, union, compress, decompress, penalty, picksplit, same) and create a GiST operator class — these functions define how the index organizes, searches, and maintains data for the custom type', 'GiST operator classes cannot be user-defined'], correctAnswer: 1, explanation: 'A GiST operator class requires implementing 7 support functions: 1) consistent: does a key match a query? 2) union: compute union of keys. 3) compress: compress a key for storage. 4) decompress: decompress a stored key. 5) penalty: cost of inserting into a subtree. 6) picksplit: split a page into two groups. 7) same: are two keys equal? These functions define the tree structure behavior. The operators (e.g., &&, @>, <->) are mapped to strategy numbers that consistent() interprets.', codeSnippet: "-- GiST operator class requires support functions:\n-- (Simplified conceptual example)\n\n-- Strategy numbers for operators:\n-- 1: overlaps (&&)\n-- 2: contains (@>)\n-- 3: contained (<@)\n-- 7: distance (<->)\n\nCREATE OPERATOR CLASS my_gist_ops\n  FOR TYPE my_type USING gist AS\n  -- Operators:\n  OPERATOR 1 && (my_type, my_type),\n  OPERATOR 2 @> (my_type, my_type),\n  OPERATOR 3 <@ (my_type, my_type),\n  -- Support functions:\n  FUNCTION 1 my_consistent(internal, my_type, smallint, oid, internal),\n  FUNCTION 2 my_union(internal, internal),\n  FUNCTION 3 my_compress(internal),\n  FUNCTION 4 my_decompress(internal),\n  FUNCTION 5 my_penalty(internal, internal, internal),\n  FUNCTION 6 my_picksplit(internal, internal),\n  FUNCTION 7 my_same(my_type, my_type, internal);\n\n-- Now create GiST indexes:\nCREATE INDEX ON my_table\n  USING gist (my_col my_gist_ops);", tags: ['advanced', 'custom-operators', 'gist-implementation', 'support-functions'] },
  { id: 'pg-advanced-l4-079', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'How do you implement bidirectional logical replication?', options: ['Bidirectional replication is not possible', 'Use physical replication for both directions', 'Set up publications and subscriptions in both directions between two databases, using replication origins to prevent infinite loops — each server is both publisher and subscriber, with origin tracking ensuring changes are not replicated back to their source', 'Use a third-party tool like BDR exclusively'], correctAnswer: 2, explanation: 'Bidirectional logical replication creates a multi-master setup. The challenge is preventing infinite loops (change from A to B back to A). PostgreSQL uses replication origins to track where each change originated. When a subscriber applies a change, it marks it with the subscription origin. The publisher then skips changes from that origin when sending to the same subscriber. This requires careful conflict resolution since both sides can modify the same data simultaneously.', codeSnippet: "-- Server A:\nCREATE PUBLICATION pub_a FOR ALL TABLES;\nCREATE SUBSCRIPTION sub_from_b\n  CONNECTION 'host=server_b dbname=mydb'\n  PUBLICATION pub_b\n  WITH (copy_data = false, origin = 'none');\n-- origin = 'none': don't replicate already-replicated data\n\n-- Server B:\nCREATE PUBLICATION pub_b FOR ALL TABLES;\nCREATE SUBSCRIPTION sub_from_a\n  CONNECTION 'host=server_a dbname=mydb'\n  PUBLICATION pub_a\n  WITH (copy_data = false, origin = 'none');\n\n-- Conflict handling: last-write-wins trigger\nCREATE FUNCTION lww_conflict()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    BEGIN\n      RETURN NEW;\n    EXCEPTION WHEN unique_violation THEN\n      IF NEW.updated_at > OLD.updated_at THEN\n        DELETE FROM tbl WHERE id = NEW.id;\n        RETURN NEW;\n      END IF;\n      RETURN NULL; -- keep existing\n    END;\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'logical-decoding', 'bidirectional', 'multi-master'] },
  { id: 'pg-advanced-l4-080', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Background Workers', question: 'How do you implement health checks and auto-healing with background workers?', options: ['PostgreSQL has no self-healing capabilities', 'Use external monitoring tools exclusively', 'Extensions like pg_cron or custom background workers can implement periodic health checks — running diagnostic queries, detecting anomalies, sending alerts via NOTIFY, and performing automatic corrective actions like killing long queries, refreshing statistics, or reindexing', 'Health checks require superuser intervention'], correctAnswer: 3, explanation: 'Background worker-based health monitoring: 1) Schedule periodic checks with pg_cron. 2) Monitor table bloat and auto-vacuum. 3) Kill queries exceeding time limits. 4) Detect index corruption and trigger REINDEX. 5) Monitor replication lag and alert. 6) Check connection counts and terminate idle connections. 7) Refresh stale statistics. This creates a self-managing database that handles common operational issues automatically, reducing DBA intervention.', codeSnippet: "-- Health check jobs with pg_cron:\n\n-- Kill queries longer than 30 minutes:\nSELECT cron.schedule('kill-long-queries', '*/5 * * * *',\n$$\n  SELECT pg_terminate_backend(pid)\n  FROM pg_stat_activity\n  WHERE state = 'active'\n    AND query_start < now() - interval '30 minutes'\n    AND usename != 'postgres'\n    AND query NOT LIKE 'autovacuum%';\n$$);\n\n-- Monitor and alert on replication lag:\nSELECT cron.schedule('check-replication', '* * * * *',\n$$\n  DO $do$\n  DECLARE lag NUMERIC;\n  BEGIN\n    SELECT extract(epoch from replay_lag) INTO lag\n    FROM pg_stat_replication LIMIT 1;\n    IF lag > 300 THEN\n      PERFORM pg_notify('alerts',\n        'Replication lag: ' || lag || ' seconds');\n    END IF;\n  END $do$;\n$$);\n\n-- Auto-analyze tables with stale stats:\nSELECT cron.schedule('auto-analyze', '0 * * * *',\n$$\n  SELECT schemaname || '.' || relname\n  FROM pg_stat_user_tables\n  WHERE n_mod_since_analyze > 10000;\n$$);", tags: ['advanced', 'background-workers', 'health-checks', 'auto-healing'] },
  { id: 'pg-advanced-l4-081', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'JIT Compilation', question: 'How do you use JIT with complex analytical queries for maximum performance?', options: ['JIT provides no benefit for analytical queries', 'Enable JIT and increase parallelism for analytical workloads — lower jit_above_cost thresholds, enable jit_inline_above_cost and jit_optimize_above_cost, and combine with parallel query workers for maximum throughput on complex aggregation and transformation queries', 'JIT slows down all analytical queries', 'Use stored procedures instead of JIT'], correctAnswer: 0, explanation: 'For analytical workloads, JIT provides maximum benefit: 1) Complex WHERE expressions with many conditions. 2) Computed columns with mathematical operations. 3) CASE statements with many branches. 4) Type coercions and format conversions. 5) Aggregate expressions. Configuration: lower jit_above_cost (e.g., 10000) to JIT more queries, enable inlining and optimization for full LLVM pipeline, and combine with parallel workers. The JIT overhead is amortized over millions of processed rows.', codeSnippet: "-- Optimal analytical JIT settings:\nSET jit = on;\nSET jit_above_cost = 10000;\nSET jit_inline_above_cost = 50000;\nSET jit_optimize_above_cost = 50000;\nSET max_parallel_workers_per_gather = 8;\nSET work_mem = '512MB';\n\n-- Complex analytical query (benefits from JIT):\nEXPLAIN (ANALYZE, BUFFERS)\nSELECT\n  region,\n  product_category,\n  SUM(CASE WHEN order_date >= '2024-01-01'\n    THEN quantity * unit_price * (1 - discount) END) AS ytd_revenue,\n  SUM(CASE WHEN order_date >= '2023-01-01'\n    AND order_date < '2024-01-01'\n    THEN quantity * unit_price * (1 - discount) END) AS prev_year,\n  ROUND(100.0 * (ytd - prev) / NULLIF(prev, 0), 2) AS growth_pct\nFROM orders\nJOIN products USING (product_id)\nJOIN regions USING (region_id)\nGROUP BY ROLLUP (region, product_category)\nHAVING SUM(quantity) > 100;\n\n-- JIT compiles all CASE expressions,\n-- arithmetic, and aggregate transitions\n-- Combined with 8 parallel workers = fast!", tags: ['advanced', 'jit-compilation', 'analytics', 'performance'] },
  { id: 'pg-advanced-l4-082', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Row-Level Security', question: 'How do you implement data sovereignty with RLS?', options: ['Data sovereignty requires separate databases', 'Use geographic database clusters only', 'Create RLS policies that enforce geographic data access rules — restricting which regions can view or modify data based on regulatory requirements (GDPR, data residency laws), combining with column encryption for sensitive fields and audit logging for compliance', 'Data sovereignty is an application concern only'], correctAnswer: 1, explanation: 'Data sovereignty with RLS ensures data is only accessible from authorized geographic regions or jurisdictions. Policies check the user session context (country, region) against the data jurisdiction. This enforces GDPR data residency, cross-border data transfer restrictions, and sector-specific regulations. Combined with column-level encryption (pgcrypto) for additional protection and audit logging for compliance evidence, this provides comprehensive data sovereignty enforcement.', codeSnippet: "-- Data with jurisdiction labels:\nCREATE TABLE personal_data (\n  id SERIAL PRIMARY KEY,\n  name TEXT,\n  data_jurisdiction TEXT NOT NULL,  -- 'EU', 'US', 'APAC'\n  sensitive_data BYTEA,  -- encrypted\n  created_at TIMESTAMPTZ\n);\n\nALTER TABLE personal_data\n  ENABLE ROW LEVEL SECURITY;\n\n-- Data sovereignty policy:\nCREATE POLICY sovereignty ON personal_data\n  USING (\n    data_jurisdiction = current_setting('app.user_jurisdiction')\n    OR data_jurisdiction IN (\n      SELECT target_jurisdiction\n      FROM data_transfer_agreements\n      WHERE source_jurisdiction = current_setting('app.user_jurisdiction')\n        AND agreement_active = TRUE\n        AND expires_at > now()\n    )\n  );\n\n-- EU user can see EU data + agreed jurisdictions:\nSET app.user_jurisdiction = 'EU';\nSELECT * FROM personal_data;\n-- Only EU data + jurisdictions with active\n-- data transfer agreements\n\n-- Audit trail for compliance:\nCREATE POLICY audit_access ON personal_data\n  AS RESTRICTIVE USING (\n    log_data_access('personal_data', id) OR TRUE\n  );", tags: ['advanced', 'row-level-security', 'data-sovereignty', 'gdpr'] },
  { id: 'pg-advanced-l4-083', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Spatial Indexing', question: 'How do you implement space-filling curve indexes for spatial data?', options: ['Space-filling curves are not supported in PostgreSQL', 'Use a Hilbert curve value as a B-tree indexed column — compute a space-filling curve value for each point that maps 2D coordinates to a 1D value preserving locality, enabling efficient range scans on a standard B-tree index for spatial proximity queries', 'Space-filling curves are only theoretical', 'Use PostGIS native indexes instead'], correctAnswer: 2, explanation: 'Space-filling curves (Hilbert, Z-order/Morton) map multi-dimensional coordinates to a single dimension while preserving spatial locality. Points close in 2D space tend to have close 1D values. This allows using a regular B-tree index (which is very efficient) for spatial proximity queries via range scans. The approach is used by Uber H3, Google S2, and Geohash. While PostGIS GiST is more flexible, space-filling curve indexes can be faster for simple point-in-range queries on very large datasets.', codeSnippet: "-- Using geohash as a space-filling curve:\nCREATE TABLE locations (\n  id BIGSERIAL PRIMARY KEY,\n  lat FLOAT NOT NULL,\n  lon FLOAT NOT NULL,\n  geohash TEXT GENERATED ALWAYS AS (\n    ST_GeoHash(ST_MakePoint(lon, lat), 12)\n  ) STORED\n);\n\n-- B-tree index on geohash (very efficient):\nCREATE INDEX idx_geohash ON locations (geohash);\n\n-- Proximity query using geohash prefix:\nSELECT * FROM locations\nWHERE geohash LIKE 'u33dc%'  -- ~150m precision\nORDER BY geohash;\n-- Uses B-tree index range scan!\n\n-- H3 hexagonal index (requires h3 extension):\nCREATE EXTENSION h3;\n\nALTER TABLE locations ADD COLUMN h3_index H3INDEX\n  GENERATED ALWAYS AS (\n    h3_lat_lng_to_cell(POINT(lat, lon), 9)\n  ) STORED;\n\nCREATE INDEX ON locations (h3_index);\n\n-- Find neighbors via H3:\nSELECT * FROM locations\nWHERE h3_index = ANY(\n  h3_grid_disk(h3_lat_lng_to_cell(POINT(48.86, 2.35), 9), 1)\n);", tags: ['advanced', 'spatial-indexing', 'space-filling-curve', 'geohash'] },
  { id: 'pg-advanced-l4-084', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Parallel Query', question: 'How do you use parallel query with CTEs and subqueries?', options: ['CTEs always prevent parallel execution', 'All CTEs are automatically parallelized', 'Inlined CTEs (without MATERIALIZED keyword) can participate in parallel plans, while MATERIALIZED CTEs create optimization barriers — use NOT MATERIALIZED (PG 12+) to hint the optimizer to inline CTEs, and structure subqueries to allow parallel execution', 'Subqueries cannot use parallel workers'], correctAnswer: 3, explanation: 'CTE parallelism in PostgreSQL: 1) PG 12+ defaults to inlining simple CTEs (optimizer can merge them into the main query, enabling parallel plans). 2) MATERIALIZED keyword forces CTE evaluation as a separate step (blocking parallelism). 3) NOT MATERIALIZED hints inlining. 4) Recursive CTEs are always materialized. 5) Subqueries in FROM can be parallelized if they contain parallel-safe operations. 6) Correlated subqueries may prevent parallelism depending on context.', codeSnippet: "-- CTE inlined (parallel-friendly, PG 12+):\nWITH filtered AS (\n  SELECT * FROM large_table\n  WHERE status = 'active'\n)\nSELECT COUNT(*) FROM filtered;\n-- CTE is inlined into main query\n-- Parallel Seq Scan on large_table\n\n-- Force inlining:\nWITH filtered AS NOT MATERIALIZED (\n  SELECT * FROM large_table WHERE status = 'active'\n)\nSELECT COUNT(*) FROM filtered;\n\n-- Materialized CTE (blocks parallelism):\nWITH filtered AS MATERIALIZED (\n  SELECT * FROM large_table WHERE status = 'active'\n)\nSELECT COUNT(*) FROM filtered;\n-- CTE evaluated first, then count\n-- No parallel execution for CTE step\n\n-- Subquery in FROM (parallel-friendly):\nSELECT * FROM (\n  SELECT id, SUM(amount) AS total\n  FROM large_table\n  GROUP BY id\n) sub\nWHERE total > 1000;\n-- Parallel execution possible for inner query", tags: ['advanced', 'parallel-query', 'cte', 'subquery'] },
  { id: 'pg-advanced-l4-085', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Generated Columns', question: 'How do you use generated columns for performance optimization of frequently computed expressions?', options: ['Generated columns always slow down writes', 'Pre-compute expensive expressions in generated columns to trade write-time computation for read-time performance — expressions involving string operations, mathematical calculations, JSON extraction, or date computations are computed once on write and indexed for fast reads', 'Generated columns provide no performance benefit', 'Use function indexes instead of generated columns'], correctAnswer: 0, explanation: 'Generated columns optimize read-heavy workloads by pre-computing expressions at write time. The computation happens once (on INSERT/UPDATE) instead of every query. With indexes on generated columns, queries can use efficient index scans instead of computing expressions for every row. This is especially valuable for: complex string operations, JSON field extraction, date/time bucketing, mathematical formulas, and hash computations. The tradeoff is increased write time and storage.', codeSnippet: "-- Expensive expression computed on every query:\nSELECT * FROM events\nWHERE extract(year from ts) = 2024\n  AND extract(month from ts) = 6;\n-- Expression evaluated for EVERY row!\n\n-- Generated column: compute once, index:\nALTER TABLE events ADD COLUMN event_year INT\n  GENERATED ALWAYS AS (extract(year from ts)::INT) STORED;\nALTER TABLE events ADD COLUMN event_month INT\n  GENERATED ALWAYS AS (extract(month from ts)::INT) STORED;\n\nCREATE INDEX ON events (event_year, event_month);\n\n-- Now uses index:\nSELECT * FROM events\nWHERE event_year = 2024 AND event_month = 6;\n-- Index Scan! No expression evaluation per row\n\n-- Compare with expression index (alternative):\nCREATE INDEX ON events (\n  (extract(year from ts)::INT),\n  (extract(month from ts)::INT)\n);\n-- Similar performance but:\n-- Generated column: also queryable by name\n-- Expression index: less storage", tags: ['advanced', 'generated-columns', 'performance', 'optimization'] },
  { id: 'pg-advanced-l4-086', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Custom Operators', question: 'How do you create custom comparison operators for ORDER BY optimization?', options: ['ORDER BY only works with built-in comparison', 'Use a custom sort function in application code', 'Create a complete B-tree operator family with <, <=, =, >=, > operators and a comparison function — this allows PostgreSQL to use index scans for ORDER BY queries on the custom type, avoiding expensive sort operations', 'Custom ORDER BY requires a special index type'], correctAnswer: 1, explanation: 'For ORDER BY to use an index, the type must have a B-tree operator class with all five comparison operators and a comparison support function. The comparison function returns -1, 0, or 1 for less-than, equal, greater-than. The operator family groups cross-type comparisons. Once defined, CREATE INDEX USING btree works, and ORDER BY queries can use index scans. This is essential for custom types that need sorted output (e.g., version numbers, semantic types).', codeSnippet: "-- Custom version type with natural ordering:\nCREATE TYPE semver AS (major INT, minor INT, patch INT);\n\nCREATE FUNCTION semver_cmp(a semver, b semver)\nRETURNS INT AS $$\nBEGIN\n  IF a.major != b.major THEN\n    RETURN CASE WHEN a.major < b.major THEN -1 ELSE 1 END;\n  END IF;\n  IF a.minor != b.minor THEN\n    RETURN CASE WHEN a.minor < b.minor THEN -1 ELSE 1 END;\n  END IF;\n  IF a.patch != b.patch THEN\n    RETURN CASE WHEN a.patch < b.patch THEN -1 ELSE 1 END;\n  END IF;\n  RETURN 0;\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE;\n\n-- Create all comparison operators...\n-- CREATE OPERATOR <, <=, =, >=, >\n\nCREATE OPERATOR CLASS semver_ops\n  DEFAULT FOR TYPE semver\n  USING btree AS\n  OPERATOR 1 < ,\n  OPERATOR 2 <= ,\n  OPERATOR 3 = ,\n  OPERATOR 4 >= ,\n  OPERATOR 5 > ,\n  FUNCTION 1 semver_cmp(semver, semver);\n\n-- Now ORDER BY uses index:\nCREATE INDEX ON packages (version);\nSELECT * FROM packages ORDER BY version DESC;", tags: ['advanced', 'custom-operators', 'order-by', 'btree-operator-class'] },
  { id: 'pg-advanced-l4-087', language: 'postgresql', level: 'level4', category: 'Advanced', subcategory: 'Logical Decoding', question: 'How do you monitor and troubleshoot logical replication performance?', options: ['Logical replication performance cannot be monitored', 'Use pg_stat_replication and pg_stat_subscription to monitor replication lag, throughput, and state — combine with pg_stat_replication_slots for slot-level metrics, and check pg_stat_wal for WAL generation rate to identify bottlenecks in the replication pipeline', 'Only check the subscriber log files', 'Use external monitoring tools exclusively'], correctAnswer: 2, explanation: 'Logical replication monitoring: 1) pg_stat_replication (publisher): shows connected subscribers, write/flush/replay LSN positions, and lag. 2) pg_stat_subscription (subscriber): shows subscription state, received LSN, and error info. 3) pg_stat_replication_slots: slot-level metrics (spill counts, streaming stats). 4) pg_stat_wal: WAL generation rate. Common bottlenecks: slow subscriber apply (check indexes), network latency, large transactions, and missing indexes on subscriber.', codeSnippet: "-- Publisher monitoring:\nSELECT client_addr, state,\n  pg_size_pretty(pg_wal_lsn_diff(\n    sent_lsn, replay_lsn\n  )) AS replication_lag,\n  write_lag, flush_lag, replay_lag\nFROM pg_stat_replication;\n\n-- Subscriber monitoring:\nSELECT subname, received_lsn,\n  latest_end_lsn,\n  last_msg_send_time,\n  last_msg_receipt_time\nFROM pg_stat_subscription;\n\n-- Slot statistics (PG 14+):\nSELECT slot_name,\n  spill_txns, spill_count,\n  pg_size_pretty(spill_bytes) AS spilled,\n  stream_txns, stream_count,\n  total_txns, total_bytes\nFROM pg_stat_replication_slots;\n\n-- WAL generation rate:\nSELECT\n  wal_records, wal_bytes,\n  pg_size_pretty(wal_bytes) AS wal_generated\nFROM pg_stat_wal;\n\n-- Identify slow apply on subscriber:\n-- Check for missing indexes on subscribed tables\n-- Check for long-running transactions blocking apply", tags: ['advanced', 'logical-decoding', 'monitoring', 'troubleshooting'] },
];

export default questions;
